    if (visibleForms[blockId]) {
       setEditingLogId(null);
       setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    }
  };

  const handleEditLog = (e: React.MouseEvent, log: WorkoutLog, blockId: string) => {
     e.stopPropagation();
     setEditingLogId(log.id);
     setLogInputs(prev => ({ ...prev, [blockId]: { result: log.result, notes: log.notes || '' } }));
     setVisibleForms(prev => ({ ...prev, [blockId]: true }));
  };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;

    if (editingLogId) {
       onUpdateLog({
          id: editingLogId,
          userId: currentUserId,
          dayId: dayId,
          sectionTitle: blockTitle,
          result: input.result,
          notes: input.notes,
          date: new Date().toISOString()
       });
       setEditingLogId(null);
    } else {
       onAddLog({
         id: Date.now().toString(),
         userId: currentUserId,
         dayId: dayId,
         sectionTitle: blockTitle, 
         result: input.result,
         notes: input.notes,
         date: new Date().toISOString()
       });
    }
    setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    setVisibleForms(prev => ({ ...prev, [blockId]: false }));
  };

  const handleConfirmNoTraining = () => {
    if (!noTrainReason) return;
    onAddLog({
      id: Date.now().toString(),
      userId: currentUserId,
      dayId: activeDay.id,
      sectionTitle: 'Asistencia',
      result: 'No entrené hoy',
      notes: `Motivo: ${noTrainReason}. ${noTrainNotes}`,
      date: new Date().toISOString()
    });
    setShowNoTrainForm(false);
    setNoTrainReason('');
    setNoTrainNotes('');
  };

  const renderWithLinks = (text: string) => {
    if (!text) return <span className="text-gray-600 italic">Sin contenido...</span>;
    const urlRegex = /((?:https?:\/\/|www\.)[^\s]+)/g;
    const parts = text.split(urlRegex);
    return parts.map((part, i) => {
      if (part.match(urlRegex)) {
        const youtubeRegex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/;
        const youtubeMatch = part.match(youtubeRegex);
        if (youtubeMatch && youtubeMatch[1]) {
          const videoId = youtubeMatch[1];
          return (
            <div key={i} className="block my-3 w-full max-w-md aspect-video rounded-xl overflow-hidden shadow-2xl border border-dark-700 bg-black">
              <iframe width="100%" height="100%" src={`https://www.youtube.com/embed/${videoId}`} title="YouTube video player" frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen className="w-full h-full"></iframe>
            </div>
          );
        }
        const href = part.startsWith('www.') ? `https://${part}` : part;
        return <a key={i} href={href} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:text-blue-300 underline break-all inline-flex items-center gap-0.5 align-top" onClick={(e) => e.stopPropagation()}>{part} <ExternalLink size={10} className="inline opacity-70" /></a>;
      }
      return part;
    });
  };

  const formatTabDate = (dateStr: string) => new Date(dateStr + 'T00:00:00').getDate();

  // Calcular adherencia semanal
  const weeklyTrainingDays = programData.days.filter(d => !d.isRestDay).length;
  const completedDays = programData.days.filter(day => {
     const dayLogs = logs.filter(l => l.dayId === day.id && l.userId === currentUserId);
     return dayLogs.some(l => l.result !== 'No entrené hoy');
  }).length;
  const adherencePct = weeklyTrainingDays > 0 ? Math.round((completedDays / weeklyTrainingDays) * 100) : 0;

  return (
    <div className="pb-24 flex flex-col h-full md:h-[calc(100vh-8rem)]">
      <div className="mb-4 shrink-0 px-2">
        <div className="flex justify-between items-center mb-2">
           <button onClick={() => onWeekChange('prev')} className="text-gray-500 hover:text-white p-1"><ChevronLeft size={24}/></button>
           <h1 className="text-3xl font-black text-blood-500 italic uppercase tracking-tighter text-center">Wild Blood</h1>
           <button onClick={() => onWeekChange('next')} className="text-gray-500 hover:text-white p-1"><ChevronRight size={24}/></button>
        </div>

        {/* Widget de Adherencia */}
        <div className="flex justify-between items-center bg-dark-800 border border-dark-700 rounded-xl px-4 py-2 mb-2">
           <div className="flex flex-col">
              <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Adherencia Semanal</span>
              <span className="text-lg font-black text-white">{completedDays} / {weeklyTrainingDays} <span className="text-xs text-blood-500">Días</span></span>
           </div>
           <div className="flex items-center gap-2">
              <div className="w-12 h-12 rounded-full border-4 border-dark-900 flex items-center justify-center relative">
                 <svg className="w-full h-full transform -rotate-90">
                    <circle cx="24" cy="24" r="20" stroke="currentColor" strokeWidth="4" fill="transparent" className="text-dark-900" />
                    <circle cx="24" cy="24" r="20" stroke="currentColor" strokeWidth="4" fill="transparent" strokeDasharray={2 * Math.PI * 20} strokeDashoffset={2 * Math.PI * 20 * (1 - adherencePct/100)} className="text-blood-500" />
                 </svg>
                 <span className="absolute text-[10px] font-black text-white">{adherencePct}%</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex overflow-x-auto gap-2 px-2 pb-2 mb-2 no-scrollbar shrink-0">
        {programData.days.map((day) => {
          const isSelected = selectedDayId === day.id;
          const dayLogs = logs.filter(l => l.dayId === day.id && l.userId === currentUserId);
          const didNotTrain = dayLogs.some(l => l.result === 'No entrené hoy');
          const hasRegularLogs = dayLogs.some(l => l.result !== 'No entrené hoy');

          return (
            <button
              key={day.id}
              onClick={() => setSelectedDayId(day.id)}
              className={`flex flex-col items-center justify-center min-w-[4.5rem] py-3 rounded-xl border transition-all relative ${isSelected ? 'bg-blood-600 border-blood-500 text-white shadow-lg shadow-blood-900/40 transform scale-105 z-10' : 'bg-dark-800 border-dark-700 text-gray-400 hover:bg-dark-700'}`}
            >
              <span className="text-[10px] font-bold uppercase tracking-wider mb-1">{day.dayName.substring(0, 3)}</span>
              <span className="text-lg font-black leading-none mb-1">{formatTabDate(day.date)}</span>
              {didNotTrain ? (
                <XCircle size={14} className={isSelected ? 'text-white' : 'text-red-500'} />
              ) : hasRegularLogs ? (
                <CheckCircle size={14} className={isSelected ? 'text-white' : 'text-green-500'} />
              ) : day.isRestDay ? (
                <Coffee size={14} className={isSelected ? 'text-white' : 'text-gray-600'} />
              ) : (
                <div className={`w-3 h-3 rounded-full border-2 ${isSelected ? 'border-white' : 'border-gray-600'}`}></div>
              )}
            </button>
          );
        })}
      </div>

      <div className="flex-1 overflow-y-auto px-2 pb-4">
        <div className={`min-h-full flex flex-col rounded-2xl border overflow-hidden ${activeDay.isRestDay ? 'bg-dark-900 border-dark-800' : 'bg-dark-800 border-dark-700'}`}>
          <div className="bg-dark-900/50 p-4 border-b border-dark-700 shrink-0">
            <div className="flex justify-between items-start">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-blood-500 font-black text-sm uppercase tracking-wider flex items-center gap-2">
                    <Calendar size={14} /> {activeDay.dayName} {formatTabDate(activeDay.date)}
                  </span>
                  {activeDay.isRestDay && <span className="text-[10px] bg-dark-700 px-2 py-0.5 rounded text-gray-400 font-bold uppercase">Descanso</span>}
                </div>
                {userRole === 'COACH' ? (
                  <div className="space-y-2 mt-2">
                    <input className="w-full bg-dark-900 border border-dark-700 rounded px-2 py-2 text-white font-bold text-lg focus:border-blood-500 focus:outline-none" value={activeDay.title} onChange={(e) => handleDayChange('title', e.target.value)} placeholder="Título del WOD" />
                    <div className="flex items-center gap-2"><Dumbbell size={14} className="text-blood-500"/><input className="flex-1 bg-dark-900 border border-dark-700 rounded px-2 py-1 text-sm text-gray-300 focus:border-blood-500 focus:outline-none" value={activeDay.focus} onChange={(e) => handleDayChange('focus', e.target.value)} placeholder="Enfoque (ej: Pierna)"/></div>
                    <label className="flex items-center gap-2 text-xs text-gray-400 cursor-pointer pt-1"><input type="checkbox" checked={activeDay.isRestDay} onChange={(e) => handleDayChange('isRestDay', e.target.checked)} className="accent-blood-600"/>Marcar como Rest Day</label>
                  </div>
                ) : (
                  <>
                    <h2 className={`font-black text-2xl uppercase italic ${activeDay.isRestDay ? 'text-gray-500 line-through decoration-blood-500' : 'text-white'}`}>{activeDay.title}</h2>
                    {!activeDay.isRestDay && <p className="text-xs text-blood-400 font-bold uppercase tracking-wider flex items-center gap-1 mt-1"><Dumbbell size={12} /> {activeDay.focus}</p>}
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="flex-1 p-4 space-y-4">
             {activeBlocks.map((block) => {
               const blockLogs = logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId && l.sectionTitle === block.title);
               const isFormVisible = visibleForms[block.id];
               return (
                <div key={block.id} className={`rounded-xl border relative transition-all group ${userRole === 'COACH' ? 'bg-dark-900 border-dark-600 p-2' : 'bg-dark-900/30 border-dark-700/50 p-4'}`}>
                   {userRole === 'COACH' && (
                      <div className="flex justify-between items-center mb-2 pb-2 border-b border-dark-700">
                         <input value={block.title} onChange={(e) => handleUpdateBlock(block.id, 'title', e.target.value)} className="bg-transparent text-xs font-black uppercase tracking-wider text-blood-500 focus:outline-none w-full" placeholder="TÍTULO SECCIÓN" />
                         <div className="flex items-center gap-1">
                           <button type="button" onClick={(e) => handleDuplicateBlock(e, block.id)} className="text-gray-600 hover:text-blue-400 p-2 rounded hover:bg-dark-800 transition-colors" title="Duplicar"><Copy size={14} /></button>
                           <button type="button" onClick={(e) => handleDeleteBlock(e, block.id)} className="text-gray-600 hover:text-red-500 p-2 rounded hover:bg-dark-800 transition-colors" title="Eliminar"><Trash2 size={14} /></button>
                         </div>
                      </div>
                   )}
                   {userRole === 'COACH' ? (
                      <AutoResizeTextarea value={block.content} onChange={(e) => handleUpdateBlock(block.id, 'content', e.target.value)} placeholder="Escribe el entrenamiento aquí..." className="w-full bg-transparent text-gray-200 font-mono text-sm leading-relaxed focus:outline-none min-h-[60px]" />
                   ) : (
                      <>
                        {block.title && <h3 className="text-xs font-black text-blood-500 uppercase tracking-widest mb-2 border-l-2 border-blood-500 pl-2">{block.title}</h3>}
                        <div className="whitespace-pre-wrap font-mono text-sm text-gray-300 leading-relaxed mb-4">{renderWithLinks(block.content)}</div>
                        {!activeDay.isRestDay && (
                           <div className="mt-4 pt-4 border-t border-dark-700/50">
                              {blockLogs.length > 0 && (
                                 <div className="mb-3 space-y-2">
                                    {blockLogs.map(log => (
                                       <div key={log.id} className="flex justify-between items-center bg-dark-900/50 p-2 rounded text-xs border border-dark-700/50">
                                          <div><span className="text-blood-400 font-bold mr-2">{log.result}</span>{log.notes && <span className="text-gray-500 italic">"{log.notes}"</span>}</div>
                                          <div className="flex items-center gap-2"><span className="text-gray-600 text-[10px]">{new Date(log.date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span><button onClick={(e) => handleEditLog(e, log, block.id)} className="text-gray-600 hover:text-blue-400 transition-colors p-1"><Edit2 size={12} /></button><button onClick={(e) => { e.stopPropagation(); onDeleteLog(log.id); }} className="text-gray-600 hover:text-red-500 transition-colors p-1"><Trash2 size={12} /></button></div>
                                       </div>
                                    ))}
                                 </div>
                              )}
                              {!isFormVisible ? (
                                <button onClick={() => toggleFormVisibility(block.id)} className="w-full border border-dark-700/50 bg-dark-800/50 hover:bg-dark-800 text-gray-400 hover:text-white py-2 rounded-lg text-xs font-bold uppercase tracking-widest transition-all flex items-center justify-center gap-2"><PlusCircle size={14} /> Registrar Resultado</button>
                              ) : (
                                <div className="animate-fade-in-up bg-dark-800 p-3 rounded-lg border border-dark-700 shadow-xl border-l-4 border-l-blood-600">
                                    <div className="flex flex-col md:flex-row gap-3">
                                      <div className="flex-1"><input type="text" placeholder="Resultado (ej: 185 lbs)" className="w-full bg-dark-900 border border-dark-600 rounded-lg p-3 text-xs text-white focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.result || ''} onChange={(e) => handleLogInputChange(block.id, 'result', e.target.value)} autoFocus /></div>
                                      <div className="flex-1"><input type="text" placeholder="Notas..." className="w-full bg-dark-900 border border-dark-600 rounded-lg p-3 text-xs text-white focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.notes || ''} onChange={(e) => handleLogInputChange(block.id, 'notes', e.target.value)} /></div>
                                    </div>
                                    <div className="flex gap-2 mt-3">
                                      <button onClick={() => toggleFormVisibility(block.id)} className="flex-1 bg-dark-700 hover:bg-dark-600 text-gray-300 p-3 rounded-lg transition-colors flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-widest"><X size={16} /> Cancelar</button>
                                      <button onClick={() => handleSaveLogForBlock(activeDay.id, block.title || 'General', block.id)} disabled={!logInputs[block.id]?.result?.trim()} className={`flex-[2] text-white p-3 rounded-lg transition-colors flex items-center justify-center gap-2 shadow-lg text-xs font-bold uppercase tracking-widest ${editingLogId ? 'bg-blue-700 hover:bg-blue-600' : 'bg-blood-600 hover:bg-blood-500'} disabled:opacity-50`}><Save size={16} /> {editingLogId ? 'Actualizar' : 'Guardar'}</button>
                                    </div>
                                </div>
                              )}
                           </div>
                        )}
                      </>
                   )}
                </div>
               );
             })}

             {/* ATHLETE: MARK AS NO-TRAINING IMPROVED */}
             {userRole === 'ATHLETE' && !activeDay.isRestDay && (
                <div className="pt-4 mt-6 border-t border-dark-700/50">
                  {!showNoTrainForm ? (
                    <button 
                      onClick={() => setShowNoTrainForm(true)}
                      className="w-full flex items-center justify-center gap-2 py-4 bg-dark-900/50 hover:bg-red-950/20 border border-red-900/20 text-red-500/70 hover:text-red-500 rounded-xl transition-all text-xs font-black uppercase tracking-[0.2em]"
                    >
                      <XCircle size={16} /> Hoy no entrené
                    </button>
                  ) : (
                    <div className="bg-dark-900 p-4 rounded-xl border border-red-900/30 animate-fade-in-up">
                       <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                          <AlertCircle size={14} /> Registrar Inasistencia
                       </h4>
                       <div className="grid grid-cols-2 gap-2 mb-4">
                          {MOTIVOS_FALTA.map(m => (
                             <button 
                               key={m.id}
                               onClick={() => setNoTrainReason(m.id)}
                               className={`flex items-center gap-2 p-2 rounded-lg text-[10px] font-bold uppercase border transition-all ${noTrainReason === m.id ? 'bg-red-600 border-red-500 text-white' : 'bg-dark-800 border-dark-700 text-gray-500'}`}
                             >
                                <m.icon size={14} /> {m.label}
                             </button>
                          ))}
                       </div>
                       <input 
                         type="text" 
                         placeholder="Comentario opcional..." 
                         className="w-full bg-dark-800 border border-dark-700 rounded-lg p-3 text-xs text-white focus:border-red-500 focus:outline-none mb-4"
                         value={noTrainNotes}
                         onChange={(e) => setNoTrainNotes(e.target.value)}
                       />
                       <div className="flex gap-2">
                          <button onClick={() => setShowNoTrainForm(false)} className="flex-1 py-3 rounded-lg bg-dark-700 text-gray-400 text-[10px] font-bold uppercase">Cancelar</button>
                          <button 
                            onClick={handleConfirmNoTraining}
                            disabled={!noTrainReason}
                            className="flex-[2] py-3 rounded-lg bg-red-600 text-white text-[10px] font-bold uppercase disabled:opacity-50"
                          >
                             Confirmar Falta
                          </button>
                       </div>
                    </div>
                  )}
                </div>
             )}

             {userRole === 'COACH' && (
                <button type="button" onClick={handleAddBlock} className="w-full py-4 rounded-xl border-2 border-dashed border-dark-700 text-gray-500 hover:border-blood-500 hover:text-blood-500 transition-all flex items-center justify-center gap-2 font-bold uppercase text-xs tracking-widest"><Plus size={16} /> Agregar Sección</button>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { User, WorkoutLog, WorkoutDay, UserRole } from '../types';
import { Search, Trophy, FileText, User as UserIcon, Filter, Download, X, Clock, CalendarDays, CheckCircle, Trash2, Calendar, XCircle, AlertCircle } from 'lucide-react';

interface LogBookProps {
  logs: WorkoutLog[];
  users: User[];
  days: WorkoutDay[];
  currentUser: User;
  onDeleteLog?: (logId: string) => void;
}

export const LogBook: React.FC<LogBookProps> = ({ logs, users, days, currentUser, onDeleteLog }) => {
  // Helper to get today's date string YYYY-MM-DD
  const getTodayStr = () => {
    const d = new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Coach States
  const [coachFilterDate, setCoachFilterDate] = useState<string>(getTodayStr());
  const [selectedAthleteId, setSelectedAthleteId] = useState<string>('ALL');

  // Export Modal State
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportType, setExportType] = useState<'WEEK' | 'MONTH'>('WEEK');
  const [exportRefDate, setExportRefDate] = useState<string>(getTodayStr());

  // Athlete States
  const [filterDate, setFilterDate] = useState<string>(getTodayStr());

  // Helper to get Details
  const getDayDetails = (dayId: string) => days.find(d => d.id === dayId);
  const getUserDetails = (userId: string) => users.find(u => u.id === userId);

  // --- EXPORT LOGIC ---
  const handleExport = () => {
    // Determine Date Range
    let startDate = new Date(exportRefDate);
    let endDate = new Date(exportRefDate);
    let filenamePrefix = 'export';

    if (exportType === 'WEEK') {
        // Find Monday
        const day = startDate.getDay();
        const diff = startDate.getDate() - day + (day === 0 ? -6 : 1);
        startDate.setDate(diff);
        startDate.setHours(0,0,0,0);

        endDate = new Date(startDate);
        endDate.setDate(startDate.getDate() + 6);
        endDate.setHours(23,59,59,999);
        filenamePrefix = `wild_blood_week_${startDate.toISOString().split('T')[0]}`;
    } else {
        // Month
        startDate.setDate(1);
        startDate.setHours(0,0,0,0);

        endDate = new Date(startDate.getFullYear(), startDate.getMonth() + 1, 0);
        endDate.setHours(23,59,59,999);
        filenamePrefix = `wild_blood_month_${startDate.getMonth()+1}_${startDate.getFullYear()}`;
    }

    // Filter Logs
    const dataToExport = logs.filter(log => {
        const logDate = new Date(log.date);
        const inRange = logDate >= startDate && logDate <= endDate;
        const matchAthlete = selectedAthleteId === 'ALL' || log.userId === selectedAthleteId;
        return inRange && matchAthlete;
    }).sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    if (dataToExport.length === 0) {
        alert("No hay datos para exportar en este rango.");
        return;
    }

    // Generate CSV
    const headers = ['Fecha', 'Atleta', 'Día', 'Sección', 'Entrenamiento', 'Resultado', 'Notas'];
    const rows = dataToExport.map(log => {
        const athlete = getUserDetails(log.userId);
        const day = getDayDetails(log.dayId);

        const cleanNotes = log.notes ? log.notes.replace(/"/g, '""') : '';
        const cleanResult = log.result ? log.result.replace(/"/g, '""') : '';
        const cleanSection = log.sectionTitle ? log.sectionTitle.replace(/"/g, '""') : '';

        return [
            new Date(log.date).toLocaleDateString(),
            `"${athlete?.fullName || athlete?.username || 'Unknown'}"`,
            `"${day?.dayName || 'Unknown'}"`,
            `"${cleanSection}"`,
            `"${day?.title || ''}"`,
            `"${cleanResult}"`,
            `"${cleanNotes}"`
        ];
    });

    const csvContent = '\ufeff' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `${filenamePrefix}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setShowExportModal(false);
  };


  // --- COACH VIEW LOGIC (FILTERED TABLE) ---
  const coachFilteredLogs = useMemo(() => {
    return logs.filter(log => {
      // Date Filter
      const logDateObj = new Date(log.date);
      const logDateStr = `${logDateObj.getFullYear()}-${String(logDateObj.getMonth() + 1).padStart(2, '0')}-${String(logDateObj.getDate()).padStart(2, '0')}`;
      const matchDate = logDateStr === coachFilterDate;

      // Athlete Filter
      const matchAthlete = selectedAthleteId === 'ALL' || log.userId === selectedAthleteId;

      return matchDate && matchAthlete;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [logs, coachFilterDate, selectedAthleteId]);

  // --- ATHLETE VIEW LOGIC ---
  const myFilteredLogs = useMemo(() => {
    return logs
      .filter(log => {
         const isUser = log.userId === currentUser.id;
         const logDateObj = new Date(log.date);
         const logDateStr = `${logDateObj.getFullYear()}-${String(logDateObj.getMonth() + 1).padStart(2, '0')}-${String(logDateObj.getDate()).padStart(2, '0')}`;
         const isDateMatch = logDateStr === filterDate;

         return isUser && isDateMatch;
      })
      .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [logs, currentUser.id, filterDate]);


  if (currentUser.role === 'COACH') {
    return (
      <div className="pb-24 px-4">
        <div className="mb-6 text-center">
          <h1 className="text-3xl font-black text-blood-500 italic uppercase tracking-tighter">
            Análisis de Resultados
          </h1>
          <p className="text-gray-400 mt-2 text-sm">Monitorea el progreso de tus atletas por fecha</p>
        </div>

        {/* --- FILTERS PANEL --- */}
        <div className="bg-dark-800 p-5 rounded-2xl border border-dark-700 mb-6 shadow-lg">
          <div className="flex justify-between items-center mb-4">
             <div className="text-xs uppercase text-gray-500 font-bold flex items-center gap-2">
                <Filter size={14} /> Filtros
             </div>
             {(coachFilterDate !== getTodayStr() || selectedAthleteId !== 'ALL') && (
               <button 
