import { Save, Ruler, Weight, Activity, Timer, Dumbbell, ShieldCheck } from 'lucide-react';

interface AthleteProfileProps {
  userId: string;
  records: AthleteRecord[];
  onSaveRecord: (category: 'BIOMETRICS' | 'LIFTING' | 'GYMNASTICS' | 'MONO', exercise: string, value: string, unit: string) => Promise<void>;
  isCoachView?: boolean;
}

export const AthleteProfile: React.FC<AthleteProfileProps> = ({ records, onSaveRecord, isCoachView = false }) => {
  const [localRecords, setLocalRecords] = useState<Record<string, string>>({});
  const [liftUnit, setLiftUnit] = useState<'lbs' | 'kg'>('lbs');
  const [saving, setSaving] = useState<string | null>(null);

  useEffect(() => {
    const map: Record<string, string> = {};
    records.forEach(r => { map[r.exercise] = r.value; });
    setLocalRecords(map);
  }, [records]);

  const handleInputChange = (exercise: string, value: string) => {
    setLocalRecords(prev => ({ ...prev, [exercise]: value }));
  };

  const handleSaveCategory = async (category: 'BIOMETRICS' | 'LIFTING' | 'GYMNASTICS' | 'MONO', exercises: string[], unitOverride?: string) => {
    setSaving(category);
    try {
      const promises = exercises.map(ex => {
        const val = localRecords[ex];
        const unit = unitOverride || (category === 'LIFTING' ? liftUnit : category === 'GYMNASTICS' ? 'reps' : 'time');
        return val !== undefined ? onSaveRecord(category, ex, val, unit) : Promise.resolve();
      });
      await Promise.all(promises);
    } catch (e) { console.error(e); alert('Error al guardar.'); }
    finally { setSaving(null); }
  };

  const renderSection = (title: string, icon: React.ReactNode, category: string, exercises: string[], unitLabel?: string) => (
    <div className="bg-dark-900 border border-dark-800 rounded-3xl p-6 md:p-8 shadow-xl">
       <div className="flex justify-between items-center mb-8 border-b border-dark-800 pb-4">
          <h3 className="text-xl font-black text-white italic uppercase flex items-center gap-3">
             <span className="text-blood-500">{icon}</span>
             {title}
          </h3>
          {!isCoachView && (
             <button onClick={() => handleSaveCategory(category as any, exercises)} disabled={saving === category} className="flex items-center gap-2 bg-blood-600 hover:bg-blood-500 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-blood-900/20 disabled:opacity-50">
                <Save size={14} /> {saving === category ? 'Sincronizando...' : 'Guardar Sección'}
             </button>
          )}
       </div>

       <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {exercises.map(ex => (
             <div key={ex} className="space-y-2 group">
                <label className="text-[9px] font-black uppercase text-gray-500 tracking-wider group-hover:text-blood-500 transition-colors">{ex}</label>
                <div className="relative">
                   <input 
                     type="text" 
                     value={localRecords[ex] || ''} 
                     onChange={(e) => handleInputChange(ex, e.target.value)}
                     placeholder="0"
                     className="w-full bg-dark-950 border border-dark-800 rounded-xl p-3 text-white font-mono text-sm focus:border-blood-500 focus:outline-none transition-all"
                   />
                   <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[8px] font-black text-dark-700 uppercase">{unitLabel || (category === 'LIFTING' ? liftUnit : 'unit')}</span>
                </div>
             </div>
          ))}
       </div>
    </div>
  );

  return (
    <div className="space-y-10">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
         <div className="bg-dark-900 border border-dark-800 rounded-3xl p-6 shadow-xl flex flex-col justify-between">
            <h3 className="text-[10px] font-black text-blood-500 uppercase tracking-widest mb-4 flex items-center gap-2"><Activity size={14}/> Biometría Vital</h3>
            <div className="grid grid-cols-2 gap-4">
               <div className="space-y-2">
                  <label className="text-[9px] font-black text-gray-500 uppercase">Peso Corporal</label>
                  <div className="relative"><input type="text" value={localRecords['Weight'] || ''} onChange={(e) => handleInputChange('Weight', e.target.value)} className="w-full bg-dark-950 border border-dark-800 rounded-xl p-3 text-white text-sm" placeholder="85kg"/><Weight size={14} className="absolute right-3 top-3.5 text-dark-700"/></div>
               </div>
               <div className="space-y-2">
                  <label className="text-[9px] font-black text-gray-500 uppercase">Altura</label>
                  <div className="relative"><input type="text" value={localRecords['Height'] || ''} onChange={(e) => handleInputChange('Height', e.target.value)} className="w-full bg-dark-950 border border-dark-800 rounded-xl p-3 text-white text-sm" placeholder="1.80m"/><Ruler size={14} className="absolute right-3 top-3.5 text-dark-700"/></div>
               </div>
            </div>
            <button onClick={() => handleSaveCategory('BIOMETRICS', ['Weight', 'Height'], 'unit')} className="mt-6 w-full py-3 bg-dark-800 hover:bg-dark-700 text-white text-[10px] font-black uppercase rounded-xl transition-all">Guardar Biometría</button>
         </div>

         <div className="bg-gradient-to-br from-blood-900/20 to-dark-900 border border-blood-900/30 rounded-3xl p-6 shadow-xl relative overflow-hidden flex flex-col justify-center items-center text-center">
            <ShieldCheck size={48} className="text-blood-500 mb-4 opacity-50"/>
            <h3 className="text-xl font-black text-white italic uppercase tracking-tighter mb-2">Wild Status</h3>
            <p className="text-xs text-gray-400 font-medium px-4">Tus récords alimentan el ecosistema. Mantén tus números al día para un entrenamiento de precisión.</p>
            <div className="absolute top-0 right-0 w-32 h-32 bg-blood-600/5 rounded-full blur-3xl -mr-10 -mt-10"></div>
         </div>
      </div>

      <div className="flex bg-dark-900 p-1 rounded-2xl border border-dark-800 w-fit mx-auto">
         <button onClick={() => setLiftUnit('lbs')} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${liftUnit === 'lbs' ? 'bg-blood-600 text-white' : 'text-gray-500'}`}>LBS</button>
