};

export const sendMessageToCoach = async (chat: Chat, message: string): Promise<string> => {
  try {
    // Fixed: Properly extracting text from the response object
    const response: GenerateContentResponse = await chat.sendMessage({ message });
    return response.text || "Lo siento, hubo un error al procesar tu mensaje.";
  } catch (error) {
    console.error("Error communicating with Gemini:", error);
    return "Error de conexión con el entrenador IA.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ProgramWeek, WorkoutDay, UserRole, WorkoutLog, WorkoutBlock } from '../types';
import { Dumbbell, Save, Calendar, CheckCircle, Coffee, Plus, Trash2, Copy, ExternalLink, ChevronLeft, ChevronRight, Edit2, X, PlusCircle, XCircle, AlertCircle, Clock, HeartPulse, Plane, ZapOff } from 'lucide-react';

interface WildBloodViewProps {
  programData: ProgramWeek;
  setProgramData: (data: ProgramWeek) => void;
  onUpdateDay: (day: WorkoutDay) => void;
  onWeekChange: (direction: 'prev' | 'next') => void;
  userRole: UserRole;
  logs: WorkoutLog[];
  onAddLog: (log: WorkoutLog) => void;
  onDeleteLog: (logId: string) => void;
  onUpdateLog: (log: WorkoutLog) => void;
  currentUserId: string;
}

const MOTIVOS_FALTA = [
  { id: 'Lesión', icon: HeartPulse, label: 'Lesión/Dolor' },
  { id: 'Tiempo', icon: Clock, label: 'Trabajo/Tiempo' },
  { id: 'Salud', icon: AlertCircle, label: 'Enfermedad' },
  { id: 'Viaje', icon: Plane, label: 'Viaje' },
  { id: 'Descanso', icon: ZapOff, label: 'Fatiga/Descanso' },
];

const AutoResizeTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = (props) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  };
  useEffect(() => { adjustHeight(); }, [props.value]);
  return (
    <textarea
      ref={textareaRef}
      {...props}
      onChange={(e) => { adjustHeight(); if (props.onChange) props.onChange(e); }}
      className={`${props.className} overflow-hidden resize-none box-border`}
      rows={1}
    />
  );
};

export const WildBloodView: React.FC<WildBloodViewProps> = ({ programData, onUpdateDay, onWeekChange, userRole, logs, onAddLog, onDeleteLog, onUpdateLog, currentUserId }) => {
  const getTodayId = () => {
     const d = new Date();
     return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const [selectedDayId, setSelectedDayId] = useState<string>(getTodayId());
  const [logInputs, setLogInputs] = useState<Record<string, {result: string, notes: string}>>({});
  const [visibleForms, setVisibleForms] = useState<Record<string, boolean>>({});
  const [editingLogId, setEditingLogId] = useState<string | null>(null);
  const [showNoTrainForm, setShowNoTrainForm] = useState(false);
  const [noTrainReason, setNoTrainReason] = useState('');
  const [noTrainNotes, setNoTrainNotes] = useState('');

  useEffect(() => {
     const exists = programData.days.find(d => d.id === selectedDayId);
     if (!exists && programData.days.length > 0) setSelectedDayId(programData.days[0].id);
  }, [programData]);

  const activeDay = programData.days.find(d => d.id === selectedDayId) || programData.days[0] || { id: 'temp', date: '', dayName: '', title: '', focus: '', content: '', blocks: [], isRestDay: false };
  const activeBlocks = activeDay.blocks || [];

  const handleDayChange = (field: keyof WorkoutDay, value: any) => {
    if (userRole !== 'COACH') return;
    onUpdateDay({ ...activeDay, [field]: value });
  };

  const handleUpdateBlock = (blockId: string, field: keyof WorkoutBlock, value: string) => {
    if (userRole !== 'COACH') return;
    const newBlocks = activeBlocks.map(b => b.id === blockId ? { ...b, [field]: value } : b);
    handleDayChange('blocks', newBlocks);
  };

  const generateId = () => Date.now().toString() + Math.random().toString(36).substr(2, 5);

  const handleAddBlock = () => handleDayChange('blocks', [...activeBlocks, { id: generateId(), title: 'Nueva Sección', content: '' }]);
  const handleDuplicateBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const blockToCopy = activeBlocks.find(b => b.id === blockId);
    if (!blockToCopy) return;
    const newBlocks = [...activeBlocks];
    newBlocks.splice(activeBlocks.findIndex(b => b.id === blockId) + 1, 0, { ...blockToCopy, id: generateId(), title: `${blockToCopy.title} (Copia)` });
    handleDayChange('blocks', newBlocks);
  };
  const handleDeleteBlock = (e: React.MouseEvent, blockId: string) => { e.stopPropagation(); handleDayChange('blocks', activeBlocks.filter(b => b.id !== blockId)); };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;
    if (editingLogId) onUpdateLog({ id: editingLogId, userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    else onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    setVisibleForms(prev => ({ ...prev, [blockId]: false }));
    setEditingLogId(null);
  };

  const handleConfirmNoTraining = () => {
    if (!noTrainReason) return;
    onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId: activeDay.id, sectionTitle: 'Asistencia', result: 'No entrené hoy', notes: `Motivo: ${noTrainReason}. ${noTrainNotes}`, date: new Date().toISOString() });
    setShowNoTrainForm(false); setNoTrainReason(''); setNoTrainNotes('');
  };

  const formatTabDate = (dateStr: string) => new Date(dateStr + 'T00:00:00').getDate();
  const weeklyTrainingDays = programData.days.filter(d => !d.isRestDay).length;
  const completedDays = programData.days.filter(day => logs.some(l => l.dayId === day.id && l.userId === currentUserId && l.result !== 'No entrené hoy')).length;
  const adherencePct = weeklyTrainingDays > 0 ? Math.round((completedDays / weeklyTrainingDays) * 100) : 0;

  return (
    <div className="flex flex-col h-full animate-fade-in">
      <div className="mb-6 px-4 md:px-0">
        <div className="flex justify-between items-center mb-6">
           <div className="flex items-center gap-4">
              <button onClick={() => onWeekChange('prev')} className="bg-dark-800 p-2 rounded-xl text-gray-500 hover:text-white transition-all"><ChevronLeft size={20}/></button>
              <div className="text-center">
                 <h1 className="text-4xl md:text-5xl font-black text-blood-500 italic uppercase tracking-tighter leading-none">Wild Blood</h1>
                 <p className="text-[10px] text-gray-500 uppercase tracking-[0.3em] font-bold mt-1">Semana del {programData.startDate}</p>
              </div>
              <button onClick={() => onWeekChange('next')} className="bg-dark-800 p-2 rounded-xl text-gray-500 hover:text-white transition-all"><ChevronRight size={20}/></button>
           </div>

           <div className="hidden md:flex items-center gap-6 bg-dark-900/50 p-4 rounded-2xl border border-dark-800">
              <div className="flex flex-col">
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Adherencia</span>
                 <span className="text-2xl font-black text-white">{adherencePct}%</span>
              </div>
              <div className="flex gap-1">
                 {programData.days.map(d => {
                   const hasLog = logs.some(l => l.dayId === d.id && l.userId === currentUserId && l.result !== 'No entrené hoy');
                   const didNotTrain = logs.some(l => l.dayId === d.id && l.userId === currentUserId && l.result === 'No entrené hoy');
                   return <div key={d.id} className={`w-2 h-10 rounded-full ${hasLog ? 'bg-green-500' : didNotTrain ? 'bg-red-500' : d.isRestDay ? 'bg-dark-700' : 'bg-dark-800'}`}></div>;
                 })}
              </div>
           </div>
        </div>

        <div className="flex overflow-x-auto gap-3 pb-2 no-scrollbar">
          {programData.days.map((day) => {
            const isSelected = selectedDayId === day.id;
            const dayLogs = logs.filter(l => l.dayId === day.id && l.userId === currentUserId);
            const didNotTrain = dayLogs.some(l => l.result === 'No entrené hoy');
            const hasRegularLogs = dayLogs.some(l => l.result !== 'No entrené hoy');
            return (
              <button key={day.id} onClick={() => setSelectedDayId(day.id)} className={`flex flex-col items-center justify-center min-w-[5rem] md:min-w-[7rem] py-4 rounded-2xl border transition-all ${isSelected ? 'bg-blood-600 border-blood-500 text-white shadow-2xl scale-105 z-10' : 'bg-dark-900 border-dark-800 text-gray-500 hover:border-dark-600'}`}>
                <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-70">{day.dayName}</span>
                <span className="text-xl font-black">{formatTabDate(day.date)}</span>
                <div className="mt-2">
                  {didNotTrain ? <XCircle size={16} className="text-red-400" /> : hasRegularLogs ? <CheckCircle size={16} className="text-green-400" /> : day.isRestDay ? <Coffee size={16} className="opacity-40" /> : <div className="w-2 h-2 rounded-full border-2 border-current opacity-20"></div>}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex-1 px-4 md:px-0 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className={`lg:col-span-8 rounded-3xl border overflow-hidden transition-all ${activeDay.isRestDay ? 'bg-dark-950 border-dark-800' : 'bg-dark-900 border-dark-800 shadow-2xl shadow-black/50'}`}>
          <div className="p-6 md:p-8 border-b border-dark-800 bg-dark-900/50">
             <div className="flex items-center gap-3 mb-2">
                <Calendar size={18} className="text-blood-500" />
                <span className="text-xs font-black text-blood-500 uppercase tracking-widest">{activeDay.dayName} {formatTabDate(activeDay.date)}</span>
             </div>
             {userRole === 'COACH' ? (
                <div className="space-y-4">
                   <input className="w-full bg-dark-950 border border-dark-700 rounded-xl px-4 py-3 text-white font-black text-3xl italic uppercase focus:border-blood-500 focus:outline-none transition-all" value={activeDay.title} onChange={(e) => handleDayChange('title', e.target.value)} placeholder="TÍTULO DEL WOD" />
                   <div className="flex items-center gap-3"><Dumbbell size={18} className="text-blood-500"/><input className="flex-1 bg-dark-950 border border-dark-700 rounded-xl px-4 py-2 text-sm font-bold text-gray-300 focus:border-blood-500 focus:outline-none" value={activeDay.focus} onChange={(e) => handleDayChange('focus', e.target.value)} placeholder="Enfoque de entrenamiento..."/></div>
                   <label className="flex items-center gap-3 text-xs text-gray-400 cursor-pointer select-none"><input type="checkbox" checked={activeDay.isRestDay} onChange={(e) => handleDayChange('isRestDay', e.target.checked)} className="w-4 h-4 rounded accent-blood-600"/> MARCAR COMO DÍA DE DESCANSO</label>
                </div>
             ) : (
                <>
                   <h2 className={`text-4xl md:text-5xl font-black uppercase italic leading-tight ${activeDay.isRestDay ? 'text-gray-700' : 'text-white'}`}>{activeDay.title}</h2>
                   {!activeDay.isRestDay && <p className="flex items-center gap-2 text-sm font-black text-blood-500 uppercase tracking-[0.2em] mt-3"><Dumbbell size={16} /> {activeDay.focus}</p>}
                </>
             )}
          </div>

          <div className="p-6 md:p-8 space-y-6">
             {activeBlocks.map((block) => {
               const isFormVisible = visibleForms[block.id];
               const blockLogs = logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId && l.sectionTitle === block.title);

               return (
                <div key={block.id} className={`rounded-2xl border transition-all ${userRole === 'COACH' ? 'bg-dark-950 border-dark-700 p-4' : 'bg-dark-950/30 border-dark-800 p-6'}`}>
                   {userRole === 'COACH' && (
                      <div className="flex justify-between items-center mb-4 border-b border-dark-800 pb-2">
                         <input value={block.title} onChange={(e) => handleUpdateBlock(block.id, 'title', e.target.value)} className="bg-transparent text-sm font-black uppercase tracking-widest text-blood-500 focus:outline-none w-full" placeholder="NOMBRE DE SECCIÓN" />
                         <div className="flex gap-1"><button onClick={(e) => handleDuplicateBlock(e, block.id)} className="p-2 text-gray-600 hover:text-white transition-all"><Copy size={16}/></button><button onClick={(e) => handleDeleteBlock(e, block.id)} className="p-2 text-gray-600 hover:text-red-500 transition-all"><Trash2 size={16}/></button></div>
                      </div>
                   )}
                   {userRole === 'COACH' ? <AutoResizeTextarea value={block.content} onChange={(e) => handleUpdateBlock(block.id, 'content', e.target.value)} placeholder="Detalles de la sección..." className="w-full bg-transparent text-gray-200 font-mono text-sm leading-relaxed focus:outline-none" /> : (
                      <>
                        {block.title && <h3 className="text-xs font-black text-blood-500 uppercase tracking-[0.3em] mb-4 border-l-4 border-blood-600 pl-3">{block.title}</h3>}
                        <div className="font-mono text-sm md:text-base text-gray-300 leading-relaxed whitespace-pre-wrap">{block.content}</div>

                        {!activeDay.isRestDay && (
                           <div className="mt-8 border-t border-dark-800 pt-6">
                              {/* DISPLAY RESULTS FOR THIS BLOCK */}
                              {blockLogs.length > 0 && (
                                <div className="mb-4 space-y-3">
                                   {blockLogs.map(log => (
                                      <div key={log.id} className={`p-4 rounded-xl bg-dark-900/50 border border-dark-700 flex justify-between items-center group/log ${log.result === 'No entrené hoy' ? 'border-red-900/30 bg-red-950/10' : ''}`}>
                                         <div className="flex flex-col">
                                            <div className="flex items-center gap-2">
                                               {log.result === 'No entrené hoy' ? <XCircle size={14} className="text-red-500"/> : <Trophy size={14} className="text-yellow-600"/>}
                                               <span className={`font-mono font-black text-lg ${log.result === 'No entrené hoy' ? 'text-red-400 italic' : 'text-blood-400'}`}>
                                                  {log.result === 'No entrené hoy' ? 'FALTA' : log.result}
                                               </span>
                                            </div>
                                            {log.notes && <span className="text-[10px] text-gray-500 italic mt-1 font-medium">"{log.notes}"</span>}
                                         </div>
                                         <button onClick={() => onDeleteLog(log.id)} className="text-gray-700 hover:text-red-500 transition-colors opacity-0 group-hover/log:opacity-100">
                                            <Trash2 size={16} />
                                         </button>
                                      </div>
                                   ))}
                                </div>
                              )}

                              {!isFormVisible ? (
                                <button onClick={() => setVisibleForms(p => ({...p, [block.id]: true}))} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl border-2 border-dashed border-dark-800 text-gray-500 hover:text-white hover:border-dark-600 transition-all font-black uppercase text-xs tracking-widest"><PlusCircle size={18}/> Registrar Resultado</button>
                              ) : (
                                <div className="bg-dark-900 p-5 rounded-2xl border border-dark-700 animate-fade-in-up shadow-2xl">
                                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Resultado</label>
                                        <input type="text" placeholder="Ej: 225 lbs o 12:45..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.result || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), result: e.target.value}}))} autoFocus />
                                      </div>
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Notas (Opcional)</label>
                                        <input type="text" placeholder="Sensaciones, RPE..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.notes || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), notes: e.target.value}}))} />
                                      </div>
                                   </div>
                                   <div className="flex gap-2"><button onClick={() => setVisibleForms(p => ({...p, [block.id]: false}))} className="flex-1 py-4 text-xs font-black uppercase text-gray-500 hover:text-white transition-all">Cancelar</button><button onClick={() => handleSaveLogForBlock(activeDay.id, block.title, block.id)} className="flex-[2] py-4 bg-blood-600 hover:bg-blood-500 text-white text-xs font-black uppercase rounded-xl transition-all shadow-lg shadow-blood-900/20">Guardar Registro</button></div>
                                </div>
                              )}
                           </div>
                        )}
                      </>
                   )}
                </div>
               );
             })}
             {userRole === 'COACH' && <button onClick={handleAddBlock} className="w-full py-6 rounded-2xl border-2 border-dashed border-dark-700 text-gray-600 hover:text-blood-500 hover:border-blood-500 transition-all font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3"><Plus size={20}/> Nueva Sección</button>}
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
           {userRole === 'ATHLETE' && !activeDay.isRestDay && (
              <div className="bg-dark-900 rounded-3xl border border-dark-800 p-6 shadow-xl">
                 <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4">Opciones de hoy</h4>
                 {!showNoTrainForm ? <button onClick={() => setShowNoTrainForm(true)} className="w-full flex items-center justify-center gap-3 py-4 bg-dark-950 border border-red-900/20 text-red-500 rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-red-950/20 transition-all"><XCircle size={18}/> No entrené hoy</button> : (
                    <div className="space-y-4 animate-fade-in">
                       <p className="text-xs font-bold text-red-400">¿Por qué no entrenamos hoy?</p>
                       <div className="grid grid-cols-2 gap-2">
                          {MOTIVOS_FALTA.map(m => (
                             <button key={m.id} onClick={() => setNoTrainReason(m.id)} className={`flex items-center gap-2 p-3 rounded-xl border text-[10px] font-black uppercase transition-all ${noTrainReason === m.id ? 'bg-red-600 border-red-500 text-white' : 'bg-dark-950 border-dark-800 text-gray-600 hover:border-dark-700'}`}><m.icon size={14}/> {m.label}</button>
                          ))}
                       </div>
                       <input type="text" placeholder="Comentario..." className="w-full bg-dark-950 border border-dark-800 rounded-xl p-3 text-white text-xs" value={noTrainNotes} onChange={(e) => setNoTrainNotes(e.target.value)}/>
                       <div className="flex gap-2"><button onClick={() => setShowNoTrainForm(false)} className="flex-1 py-3 text-[10px] font-black uppercase text-gray-600">Volver</button><button onClick={handleConfirmNoTraining} disabled={!noTrainReason} className="flex-[2] py-3 bg-red-600 text-white text-[10px] font-black uppercase rounded-xl disabled:opacity-50 transition-all">Registrar Falta</button></div>
                    </div>
                 )}
              </div>
           )}

           <div className="bg-dark-900 rounded-3xl border border-dark-800 p-6 shadow-xl sticky top-6">
              <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6 flex items-center gap-2"><Trophy size={14} className="text-yellow-500"/> Todos los Resultados de Hoy</h4>
              <div className="space-y-4">
                 {logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId).length === 0 ? <p className="text-center py-10 text-gray-700 text-xs italic font-medium">No has registrado resultados todavía.</p> : logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId).map(log => (
                    <div key={log.id} className={`p-4 rounded-2xl border group relative transition-all ${log.result === 'No entrené hoy' ? 'bg-red-950/20 border-red-900/30' : 'bg-dark-950 border-dark-800'}`}>
                       <div className="flex justify-between items-start mb-2">
                          <span className="text-[9px] font-black text-blood-500 uppercase tracking-widest truncate max-w-[80%]">{log.sectionTitle || 'General'}</span>
                          <button onClick={() => onDeleteLog(log.id)} className="text-gray-700 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={12}/></button>
                       </div>
                       <div className="font-mono text-lg font-black text-white">{log.result === 'No entrené hoy' ? 'FALTA' : log.result}</div>
                       {log.notes && <p className="text-[10px] text-gray-500 italic mt-2">"{log.notes}"</p>}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

const Trophy = ({size, className}: {size:number, className?:string}) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>;

import React, { useState, useRef, useEffect } from 'react';
import { ProgramWeek, WorkoutDay, UserRole, WorkoutLog, WorkoutBlock } from '../types';
import { Dumbbell, Save, Calendar, CheckCircle, Coffee, Plus, Trash2, Copy, ExternalLink, ChevronLeft, ChevronRight, Edit2, X, PlusCircle, XCircle, AlertCircle, Clock, HeartPulse, Plane, ZapOff } from 'lucide-center';
import { Trophy } from 'lucide-react';

interface WildBloodViewProps {
  programData: ProgramWeek;
  setProgramData: (data: ProgramWeek) => void;
  onUpdateDay: (day: WorkoutDay) => void;
  onWeekChange: (direction: 'prev' | 'next') => void;
  userRole: UserRole;
  logs: WorkoutLog[];
  onAddLog: (log: WorkoutLog) => void;
  onDeleteLog: (logId: string) => void;
  onUpdateLog: (log: WorkoutLog) => void;
  currentUserId: string;
}

const MOTIVOS_FALTA = [
  { id: 'Lesión', icon: HeartPulse, label: 'Lesión/Dolor' },
  { id: 'Tiempo', icon: Clock, label: 'Trabajo/Tiempo' },
  { id: 'Salud', icon: AlertCircle, label: 'Enfermedad' },
  { id: 'Viaje', icon: Plane, label: 'Viaje' },
  { id: 'Descanso', icon: ZapOff, label: 'Fatiga/Descanso' },
];

const AutoResizeTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = (props) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  };
  useEffect(() => { adjustHeight(); }, [props.value]);
  return (
    <textarea
      ref={textareaRef}
      {...props}
      onChange={(e) => { adjustHeight(); if (props.onChange) props.onChange(e); }}
      className={`${props.className} overflow-hidden resize-none box-border`}
      rows={1}
    />
  );
};

export const WildBloodView: React.FC<WildBloodViewProps> = ({ programData, onUpdateDay, onWeekChange, userRole, logs, onAddLog, onDeleteLog, onUpdateLog, currentUserId }) => {
  const getTodayId = () => {
     const d = new Date();
     return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const [selectedDayId, setSelectedDayId] = useState<string>(getTodayId());
  const [logInputs, setLogInputs] = useState<Record<string, {result: string, notes: string}>>({});
  const [visibleForms, setVisibleForms] = useState<Record<string, boolean>>({});
  const [editingLogId, setEditingLogId] = useState<string | null>(null);
  const [showNoTrainForm, setShowNoTrainForm] = useState(false);
  const [noTrainReason, setNoTrainReason] = useState('');
  const [noTrainNotes, setNoTrainNotes] = useState('');

  useEffect(() => {
     const exists = programData.days.find(d => d.id === selectedDayId);
     if (!exists && programData.days.length > 0) setSelectedDayId(programData.days[0].id);
  }, [programData]);

  const activeDay = programData.days.find(d => d.id === selectedDayId) || programData.days[0] || { id: 'temp', date: '', dayName: '', title: '', focus: '', content: '', blocks: [], isRestDay: false };
  const activeBlocks = activeDay.blocks || [];

  const handleDayChange = (field: keyof WorkoutDay, value: any) => {
    if (userRole !== 'COACH') return;
    onUpdateDay({ ...activeDay, [field]: value });
  };

  const handleUpdateBlock = (blockId: string, field: keyof WorkoutBlock, value: string) => {
    if (userRole !== 'COACH') return;
    const newBlocks = activeBlocks.map(b => b.id === blockId ? { ...b, [field]: value } : b);
    handleDayChange('blocks', newBlocks);
  };

  const generateId = () => Date.now().toString() + Math.random().toString(36).substr(2, 5);

  const handleAddBlock = () => handleDayChange('blocks', [...activeBlocks, { id: generateId(), title: 'Nueva Sección', content: '' }]);
  const handleDuplicateBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const blockToCopy = activeBlocks.find(b => b.id === blockId);
    if (!blockToCopy) return;
    const newBlocks = [...activeBlocks];
    newBlocks.splice(activeBlocks.findIndex(b => b.id === blockId) + 1, 0, { ...blockToCopy, id: generateId(), title: `${blockToCopy.title} (Copia)` });
    handleDayChange('blocks', newBlocks);
  };
  const handleDeleteBlock = (e: React.MouseEvent, blockId: string) => { e.stopPropagation(); handleDayChange('blocks', activeBlocks.filter(b => b.id !== blockId)); };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;
    if (editingLogId) onUpdateLog({ id: editingLogId, userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    else onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    setVisibleForms(prev => ({ ...prev, [blockId]: false }));
    setEditingLogId(null);
  };

  const handleConfirmNoTraining = () => {
    if (!noTrainReason) return;
    onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId: activeDay.id, sectionTitle: 'Asistencia', result: 'No entrené hoy', notes: `Motivo: ${noTrainReason}. ${noTrainNotes}`, date: new Date().toISOString() });
    setShowNoTrainForm(false); setNoTrainReason(''); setNoTrainNotes('');
  };

  const formatTabDate = (dateStr: string) => new Date(dateStr + 'T00:00:00').getDate();
  const weeklyTrainingDays = programData.days.filter(d => !d.isRestDay).length;
  const completedDaysCount = programData.days.filter(day => logs.some(l => l.dayId === day.id && l.userId === currentUserId && l.result !== 'No entrené hoy')).length;
  const adherencePct = weeklyTrainingDays > 0 ? Math.round((completedDaysCount / weeklyTrainingDays) * 100) : 0;

  return (
    <div className="flex flex-col h-full animate-fade-in">
      <div className="mb-6 px-4 md:px-0">

        {/* HEADER CENTRADO - Siguiendo la captura */}
        <div className="flex flex-col items-center mb-6">
           <div className="flex items-center justify-between w-full max-w-md gap-4 bg-dark-900/30 p-4 rounded-2xl border border-dark-800 shadow-xl">
              <button 
                onClick={() => onWeekChange('prev')} 
                className="bg-dark-800 p-3 rounded-xl text-gray-400 hover:text-white transition-all active:scale-90"
              >
                <ChevronLeft size={24}/>
              </button>

              <div className="text-center flex-1">
                 <h1 className="text-3xl md:text-4xl font-black text-blood-600 italic uppercase tracking-tighter leading-none">Wild Blood</h1>
                 <p className="text-[10px] text-gray-500 uppercase tracking-[0.2em] font-bold mt-1 opacity-70">Semana del {programData.startDate}</p>
              </div>

              <button 
                onClick={() => onWeekChange('next')} 
                className="bg-dark-800 p-3 rounded-xl text-gray-400 hover:text-white transition-all active:scale-90"
              >
                <ChevronRight size={24}/>
              </button>
           </div>

           {/* BARRA DE PORCENTAJE - Visible en móviles y PC */}
           <div className="w-full max-w-md mt-4 px-2">
              <div className="flex justify-between items-end mb-1 px-1">
                 <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest">Adherencia Semanal</span>
                 <span className="text-xs font-black text-blood-500">{adherencePct}%</span>
              </div>
              <div className="h-1.5 w-full bg-dark-800 rounded-full overflow-hidden border border-dark-700/50">
                 <div 
                   className="h-full bg-blood-600 transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(239,68,68,0.3)]"
                   style={{ width: `${adherencePct}%` }}
                 />
              </div>
           </div>
        </div>

        {/* SELECTOR DE DÍAS */}
        <div className="flex overflow-x-auto gap-3 pb-4 no-scrollbar">
          {programData.days.map((day) => {
            const isSelected = selectedDayId === day.id;
            const dayLogs = logs.filter(l => l.dayId === day.id && l.userId === currentUserId);
            const didNotTrain = dayLogs.some(l => l.result === 'No entrené hoy');
            const hasRegularLogs = dayLogs.some(l => l.result !== 'No entrené hoy');
            return (
              <button 
                key={day.id} 
                onClick={() => setSelectedDayId(day.id)} 
                className={`flex flex-col items-center justify-center min-w-[5.5rem] md:min-w-[7.5rem] py-4 rounded-2xl border transition-all ${isSelected ? 'bg-blood-600 border-blood-500 text-white shadow-2xl scale-105 z-10' : 'bg-dark-900 border-dark-800 text-gray-500 hover:border-dark-600 active:scale-95'}`}
              >
                <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-70">{day.dayName}</span>
                <span className="text-2xl font-black leading-none">{formatTabDate(day.date)}</span>
                <div className="mt-2">
                  {didNotTrain ? <XCircle size={18} className="text-red-400" /> : hasRegularLogs ? <CheckCircle size={18} className="text-green-400" /> : day.isRestDay ? <Coffee size={18} className="opacity-40" /> : <div className="w-2.5 h-2.5 rounded-full border-2 border-current opacity-20"></div>}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex-1 px-4 md:px-0 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className={`lg:col-span-8 rounded-3xl border overflow-hidden transition-all ${activeDay.isRestDay ? 'bg-dark-950 border-dark-800' : 'bg-dark-900 border-dark-800 shadow-2xl shadow-black/50'}`}>
          <div className="p-6 md:p-8 border-b border-dark-800 bg-dark-900/50">
             <div className="flex items-center gap-3 mb-2">
                <Calendar size={18} className="text-blood-500" />
                <span className="text-xs font-black text-blood-500 uppercase tracking-widest">{activeDay.dayName} {formatTabDate(activeDay.date)}</span>
             </div>
             {userRole === 'COACH' ? (
                <div className="space-y-4">
                   <input className="w-full bg-dark-950 border border-dark-700 rounded-xl px-4 py-3 text-white font-black text-3xl italic uppercase focus:border-blood-500 focus:outline-none transition-all" value={activeDay.title} onChange={(e) => handleDayChange('title', e.target.value)} placeholder="TÍTULO DEL WOD" />
                   <div className="flex items-center gap-3"><Dumbbell size={18} className="text-blood-500"/><input className="flex-1 bg-dark-950 border border-dark-700 rounded-xl px-4 py-2 text-sm font-bold text-gray-300 focus:border-blood-500 focus:outline-none" value={activeDay.focus} onChange={(e) => handleDayChange('focus', e.target.value)} placeholder="Enfoque de entrenamiento..."/></div>
                   <label className="flex items-center gap-3 text-xs text-gray-400 cursor-pointer select-none"><input type="checkbox" checked={activeDay.isRestDay} onChange={(e) => handleDayChange('isRestDay', e.target.checked)} className="w-4 h-4 rounded accent-blood-600"/> MARCAR COMO DÍA DE DESCANSO</label>
                </div>
             ) : (
                <>
                   <h2 className={`text-4xl md:text-5xl font-black uppercase italic leading-tight ${activeDay.isRestDay ? 'text-gray-700' : 'text-white'}`}>{activeDay.title}</h2>
                   {!activeDay.isRestDay && <p className="flex items-center gap-2 text-sm font-black text-blood-500 uppercase tracking-[0.2em] mt-3"><Dumbbell size={16} /> {activeDay.focus}</p>}
                </>
             )}
          </div>

          <div className="p-6 md:p-8 space-y-6">
             {activeBlocks.map((block) => {
               const isFormVisible = visibleForms[block.id];
               const blockLogs = logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId && l.sectionTitle === block.title);

               return (
                <div key={block.id} className={`rounded-2xl border transition-all ${userRole === 'COACH' ? 'bg-dark-950 border-dark-700 p-4' : 'bg-dark-950/30 border-dark-800 p-6'}`}>
                   {userRole === 'COACH' && (
                      <div className="flex justify-between items-center mb-4 border-b border-dark-800 pb-2">
                         <input value={block.title} onChange={(e) => handleUpdateBlock(block.id, 'title', e.target.value)} className="bg-transparent text-sm font-black uppercase tracking-widest text-blood-500 focus:outline-none w-full" placeholder="NOMBRE DE SECCIÓN" />
                         <div className="flex gap-1"><button onClick={(e) => handleDuplicateBlock(e, block.id)} className="p-2 text-gray-600 hover:text-white transition-all"><Copy size={16}/></button><button onClick={(e) => handleDeleteBlock(e, block.id)} className="p-2 text-gray-600 hover:text-red-500 transition-all"><Trash2 size={16}/></button></div>
                      </div>
                   )}
                   {userRole === 'COACH' ? <AutoResizeTextarea value={block.content} onChange={(e) => handleUpdateBlock(block.id, 'content', e.target.value)} placeholder="Detalles de la sección..." className="w-full bg-transparent text-gray-200 font-mono text-sm leading-relaxed focus:outline-none" /> : (
                      <>
                        {block.title && <h3 className="text-xs font-black text-blood-500 uppercase tracking-[0.3em] mb-4 border-l-4 border-blood-600 pl-3">{block.title}</h3>}
                        <div className="font-mono text-sm md:text-base text-gray-300 leading-relaxed whitespace-pre-wrap">{block.content}</div>

                        {!activeDay.isRestDay && (
                           <div className="mt-8 border-t border-dark-800 pt-6">
                              {/* DISPLAY RESULTS FOR THIS BLOCK */}
                              {blockLogs.length > 0 && (
                                <div className="mb-4 space-y-3">
                                   {blockLogs.map(log => (
                                      <div key={log.id} className={`p-4 rounded-xl bg-dark-900/50 border border-dark-700 flex justify-between items-center group/log ${log.result === 'No entrené hoy' ? 'border-red-900/30 bg-red-950/10' : ''}`}>
                                         <div className="flex flex-col">
                                            <div className="flex items-center gap-2">
                                               {log.result === 'No entrené hoy' ? <XCircle size={14} className="text-red-500"/> : <Trophy size={14} className="text-yellow-600"/>}
                                               <span className={`font-mono font-black text-lg ${log.result === 'No entrené hoy' ? 'text-red-400 italic' : 'text-blood-400'}`}>
                                                  {log.result === 'No entrené hoy' ? 'FALTA' : log.result}
                                               </span>
                                            </div>
                                            {log.notes && <span className="text-[10px] text-gray-500 italic mt-1 font-medium">"{log.notes}"</span>}
                                         </div>
                                         <button onClick={() => onDeleteLog(log.id)} className="text-gray-700 hover:text-red-500 transition-colors opacity-0 group-hover/log:opacity-100">
                                            <Trash2 size={16} />
                                         </button>
                                      </div>
                                   ))}
                                </div>
                              )}

                              {!isFormVisible ? (
                                <button onClick={() => setVisibleForms(p => ({...p, [block.id]: true}))} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl border-2 border-dashed border-dark-800 text-gray-500 hover:text-white hover:border-dark-600 transition-all font-black uppercase text-xs tracking-widest"><PlusCircle size={18}/> Registrar Resultado</button>
                              ) : (
                                <div className="bg-dark-900 p-5 rounded-2xl border border-dark-700 animate-fade-in-up shadow-2xl">
                                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Resultado</label>
                                        <input type="text" placeholder="Ej: 225 lbs o 12:45..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.result || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), result: e.target.value}}))} autoFocus />
                                      </div>
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Notas (Opcional)</label>
                                        <input type="text" placeholder="Sensaciones, RPE..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.notes || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), notes: e.target.value}}))} />
                                      </div>
                                   </div>
                                   <div className="flex gap-2"><button onClick={() => setVisibleForms(p => ({...p, [block.id]: false}))} className="flex-1 py-4 text-xs font-black uppercase text-gray-500 hover:text-white transition-all">Cancelar</button><button onClick={() => handleSaveLogForBlock(activeDay.id, block.title, block.id)} className="flex-[2] py-4 bg-blood-600 hover:bg-blood-500 text-white text-xs font-black uppercase rounded-xl transition-all shadow-lg shadow-blood-900/20">Guardar Registro</button></div>
                                </div>
                              )}
                           </div>
                        )}
                      </>
                   )}
                </div>
               );
             })}
             {userRole === 'COACH' && <button onClick={handleAddBlock} className="w-full py-6 rounded-2xl border-2 border-dashed border-dark-700 text-gray-600 hover:text-blood-500 hover:border-blood-500 transition-all font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3"><Plus size={20}/> Nueva Sección</button>}
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
           {userRole === 'ATHLETE' && !activeDay.isRestDay && (
              <div className="bg-dark-900 rounded-3xl border border-dark-800 p-6 shadow-xl">
                 <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4">Opciones de hoy</h4>
                 {!showNoTrainForm ? <button onClick={() => setShowNoTrainForm(true)} className="w-full flex items-center justify-center gap-3 py-4 bg-dark-950 border border-red-900/20 text-red-500 rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-red-950/20 transition-all active:scale-95"><XCircle size={18}/> No entrené hoy</button> : (
                    <div className="space-y-4 animate-fade-in">
                       <p className="text-xs font-bold text-red-400">¿Por qué no entrenamos hoy?</p>
                       <div className="grid grid-cols-2 gap-2">
                          {MOTIVOS_FALTA.map(m => (
                             <button key={m.id} onClick={() => setNoTrainReason(m.id)} className={`flex items-center gap-2 p-3 rounded-xl border text-[10px] font-black uppercase transition-all ${noTrainReason === m.id ? 'bg-red-600 border-red-500 text-white' : 'bg-dark-950 border-dark-800 text-gray-600 hover:border-dark-700'}`}><m.icon size={14}/> {m.label}</button>
                          ))}
                       </div>
                       <input type="text" placeholder="Comentario..." className="w-full bg-dark-950 border border-dark-800 rounded-xl p-3 text-white text-xs" value={noTrainNotes} onChange={(e) => setNoTrainNotes(e.target.value)}/>
                       <div className="flex gap-2"><button onClick={() => setShowNoTrainForm(false)} className="flex-1 py-3 text-[10px] font-black uppercase text-gray-600">Volver</button><button onClick={handleConfirmNoTraining} disabled={!noTrainReason} className="flex-[2] py-3 bg-red-600 text-white text-[10px] font-black uppercase rounded-xl disabled:opacity-50 transition-all active:scale-95">Registrar Falta</button></div>
                    </div>
                 )}
              </div>
           )}

           <div className="bg-dark-900 rounded-3xl border border-dark-800 p-6 shadow-xl sticky top-6">
              <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6 flex items-center gap-2"><Trophy size={14} className="text-yellow-500"/> Todos los Resultados de Hoy</h4>
              <div className="space-y-4">
                 {logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId).length === 0 ? <p className="text-center py-10 text-gray-700 text-xs italic font-medium">No has registrado resultados todavía.</p> : logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId).map(log => (
                    <div key={log.id} className={`p-4 rounded-2xl border group relative transition-all ${log.result === 'No entrené hoy' ? 'bg-red-950/20 border-red-900/30' : 'bg-dark-950 border-dark-800'}`}>
                       <div className="flex justify-between items-start mb-2">
                          <span className="text-[9px] font-black text-blood-500 uppercase tracking-widest truncate max-w-[80%]">{log.sectionTitle || 'General'}</span>
                          <button onClick={() => onDeleteLog(log.id)} className="text-gray-700 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={12}/></button>
                       </div>
                       <div className="font-mono text-lg font-black text-white">{log.result === 'No entrené hoy' ? 'FALTA' : log.result}</div>
                       {log.notes && <p className="text-[10px] text-gray-500 italic mt-2">"{log.notes}"</p>}
                    </div>
                 ))}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ProgramWeek, WorkoutDay, UserRole, WorkoutLog, WorkoutBlock } from '../types';
import { 
  Dumbbell, Save, Calendar, CheckCircle, Coffee, Plus, Trash2, Copy, 
  ExternalLink, ChevronLeft, ChevronRight, Edit2, X, PlusCircle, 
  XCircle, AlertCircle, Clock, HeartPulse, Plane, ZapOff, Trophy 
} from 'lucide-react';

interface WildBloodViewProps {
  programData: ProgramWeek;
  setProgramData: (data: ProgramWeek) => void;
  onUpdateDay: (day: WorkoutDay) => void;
  onWeekChange: (direction: 'prev' | 'next') => void;
  userRole: UserRole;
  logs: WorkoutLog[];
  onAddLog: (log: WorkoutLog) => void;
  onDeleteLog: (logId: string) => void;
  onUpdateLog: (log: WorkoutLog) => void;
  currentUserId: string;
}

const MOTIVOS_FALTA = [
  { id: 'Lesión', icon: HeartPulse, label: 'Lesión/Dolor' },
  { id: 'Tiempo', icon: Clock, label: 'Trabajo/Tiempo' },
  { id: 'Salud', icon: AlertCircle, label: 'Enfermedad' },
  { id: 'Viaje', icon: Plane, label: 'Viaje' },
  { id: 'Descanso', icon: ZapOff, label: 'Fatiga/Descanso' },
];

const AutoResizeTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = (props) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  };
  useEffect(() => { adjustHeight(); }, [props.value]);
  return (
    <textarea
      ref={textareaRef}
      {...props}
      onChange={(e) => { adjustHeight(); if (props.onChange) props.onChange(e); }}
      className={`${props.className} overflow-hidden resize-none box-border`}
      rows={1}
    />
  );
};

export const WildBloodView: React.FC<WildBloodViewProps> = ({ programData, onUpdateDay, onWeekChange, userRole, logs, onAddLog, onDeleteLog, onUpdateLog, currentUserId }) => {
  const getTodayId = () => {
     const d = new Date();
     return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const [selectedDayId, setSelectedDayId] = useState<string>(getTodayId());
  const [logInputs, setLogInputs] = useState<Record<string, {result: string, notes: string}>>({});
  const [visibleForms, setVisibleForms] = useState<Record<string, boolean>>({});
  const [editingLogId, setEditingLogId] = useState<string | null>(null);
  const [showNoTrainForm, setShowNoTrainForm] = useState(false);
  const [noTrainReason, setNoTrainReason] = useState('');
  const [noTrainNotes, setNoTrainNotes] = useState('');

  useEffect(() => {
     const exists = programData.days.find(d => d.id === selectedDayId);
     if (!exists && programData.days.length > 0) setSelectedDayId(programData.days[0].id);
  }, [programData]);

  const activeDay = programData.days.find(d => d.id === selectedDayId) || programData.days[0] || { id: 'temp', date: '', dayName: '', title: '', focus: '', content: '', blocks: [], isRestDay: false };
  const activeBlocks = activeDay.blocks || [];

  const handleDayChange = (field: keyof WorkoutDay, value: any) => {
    if (userRole !== 'COACH') return;
    onUpdateDay({ ...activeDay, [field]: value });
  };

  const handleUpdateBlock = (blockId: string, field: keyof WorkoutBlock, value: string) => {
    if (userRole !== 'COACH') return;
    const newBlocks = activeBlocks.map(b => b.id === blockId ? { ...b, [field]: value } : b);
    handleDayChange('blocks', newBlocks);
  };

  const generateId = () => Date.now().toString() + Math.random().toString(36).substr(2, 5);

  const handleAddBlock = () => handleDayChange('blocks', [...activeBlocks, { id: generateId(), title: 'Nueva Sección', content: '' }]);
  const handleDuplicateBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const blockToCopy = activeBlocks.find(b => b.id === blockId);
    if (!blockToCopy) return;
    const newBlocks = [...activeBlocks];
    newBlocks.splice(activeBlocks.findIndex(b => b.id === blockId) + 1, 0, { ...blockToCopy, id: generateId(), title: `${blockToCopy.title} (Copia)` });
    handleDayChange('blocks', newBlocks);
  };
  const handleDeleteBlock = (e: React.MouseEvent, blockId: string) => { e.stopPropagation(); handleDayChange('blocks', activeBlocks.filter(b => b.id !== blockId)); };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;
    if (editingLogId) onUpdateLog({ id: editingLogId, userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    else onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    setVisibleForms(prev => ({ ...prev, [blockId]: false }));
    setEditingLogId(null);
  };

  const handleConfirmNoTraining = () => {
    if (!noTrainReason) return;
    onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId: activeDay.id, sectionTitle: 'Asistencia', result: 'No entrené hoy', notes: `Motivo: ${noTrainReason}. ${noTrainNotes}`, date: new Date().toISOString() });
    setShowNoTrainForm(false); setNoTrainReason(''); setNoTrainNotes('');
  };

  const formatTabDate = (dateStr: string) => new Date(dateStr + 'T00:00:00').getDate();
  const weeklyTrainingDays = programData.days.filter(d => !d.isRestDay).length;
  const completedDaysCount = programData.days.filter(day => logs.some(l => l.dayId === day.id && l.userId === currentUserId && l.result !== 'No entrené hoy')).length;
  const adherencePct = weeklyTrainingDays > 0 ? Math.round((completedDaysCount / weeklyTrainingDays) * 100) : 0;

  return (
    <div className="flex flex-col h-full animate-fade-in">
      <div className="mb-6 px-4 md:px-0">

        {/* HEADER CENTRADO */}
        <div className="flex flex-col items-center mb-6">
           <div className="flex items-center justify-between w-full max-w-md gap-4 bg-dark-900/30 p-4 rounded-2xl border border-dark-800 shadow-xl">
              <button 
                onClick={() => onWeekChange('prev')} 
                className="bg-dark-800 p-3 rounded-xl text-gray-400 hover:text-white transition-all active:scale-90"
              >
                <ChevronLeft size={24}/>
              </button>

              <div className="text-center flex-1">
                 <h1 className="text-3xl md:text-4xl font-black text-blood-600 italic uppercase tracking-tighter leading-none">Wild Blood</h1>
                 <p className="text-[10px] text-gray-500 uppercase tracking-[0.2em] font-bold mt-1 opacity-70">Semana del {programData.startDate}</p>
              </div>

              <button 
                onClick={() => onWeekChange('next')} 
                className="bg-dark-800 p-3 rounded-xl text-gray-400 hover:text-white transition-all active:scale-90"
              >
                <ChevronRight size={24}/>
              </button>
           </div>

           {/* BARRA DE PORCENTAJE */}
           <div className="w-full max-w-md mt-4 px-2">
              <div className="flex justify-between items-end mb-1 px-1">
                 <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest">Adherencia Semanal</span>
                 <span className="text-xs font-black text-blood-500">{adherencePct}%</span>
              </div>
              <div className="h-1.5 w-full bg-dark-800 rounded-full overflow-hidden border border-dark-700/50">
                 <div 
                   className="h-full bg-blood-600 transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(239,68,68,0.3)]"
                   style={{ width: `${adherencePct}%` }}
                 />
              </div>
           </div>
        </div>

        {/* SELECTOR DE DÍAS */}
        <div className="flex overflow-x-auto gap-3 pb-4 no-scrollbar">
          {programData.days.map((day) => {
            const isSelected = selectedDayId === day.id;
            const dayLogs = logs.filter(l => l.dayId === day.id && l.userId === currentUserId);
            const didNotTrain = dayLogs.some(l => l.result === 'No entrené hoy');
            const hasRegularLogs = dayLogs.some(l => l.result !== 'No entrené hoy');
            return (
              <button 
                key={day.id} 
                onClick={() => setSelectedDayId(day.id)} 
                className={`flex flex-col items-center justify-center min-w-[5.5rem] md:min-w-[7.5rem] py-4 rounded-2xl border transition-all ${isSelected ? 'bg-blood-600 border-blood-500 text-white shadow-2xl scale-105 z-10' : 'bg-dark-900 border-dark-800 text-gray-500 hover:border-dark-600 active:scale-95'}`}
              >
                <span className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-70">{day.dayName}</span>
                <span className="text-2xl font-black leading-none">{formatTabDate(day.date)}</span>
                <div className="mt-2">
                  {didNotTrain ? <XCircle size={18} className="text-red-400" /> : hasRegularLogs ? <CheckCircle size={18} className="text-green-400" /> : day.isRestDay ? <Coffee size={18} className="opacity-40" /> : <div className="w-2.5 h-2.5 rounded-full border-2 border-current opacity-20"></div>}
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex-1 px-4 md:px-0 grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className={`lg:col-span-8 rounded-3xl border overflow-hidden transition-all ${activeDay.isRestDay ? 'bg-dark-950 border-dark-800' : 'bg-dark-900 border-dark-800 shadow-2xl shadow-black/50'}`}>
          <div className="p-6 md:p-8 border-b border-dark-800 bg-dark-900/50">
             <div className="flex items-center gap-3 mb-2">
                <Calendar size={18} className="text-blood-500" />
                <span className="text-xs font-black text-blood-500 uppercase tracking-widest">{activeDay.dayName} {formatTabDate(activeDay.date)}</span>
             </div>
             {userRole === 'COACH' ? (
                <div className="space-y-4">
                   <input className="w-full bg-dark-950 border border-dark-700 rounded-xl px-4 py-3 text-white font-black text-3xl italic uppercase focus:border-blood-500 focus:outline-none transition-all" value={activeDay.title} onChange={(e) => handleDayChange('title', e.target.value)} placeholder="TÍTULO DEL WOD" />
                   <div className="flex items-center gap-3"><Dumbbell size={18} className="text-blood-500"/><input className="flex-1 bg-dark-950 border border-dark-700 rounded-xl px-4 py-2 text-sm font-bold text-gray-300 focus:border-blood-500 focus:outline-none" value={activeDay.focus} onChange={(e) => handleDayChange('focus', e.target.value)} placeholder="Enfoque de entrenamiento..."/></div>
                   <label className="flex items-center gap-3 text-xs text-gray-400 cursor-pointer select-none"><input type="checkbox" checked={activeDay.isRestDay} onChange={(e) => handleDayChange('isRestDay', e.target.checked)} className="w-4 h-4 rounded accent-blood-600"/> MARCAR COMO DÍA DE DESCANSO</label>
                </div>
             ) : (
                <>
                   <h2 className={`text-4xl md:text-5xl font-black uppercase italic leading-tight ${activeDay.isRestDay ? 'text-gray-700' : 'text-white'}`}>{activeDay.title}</h2>
                   {!activeDay.isRestDay && <p className="flex items-center gap-2 text-sm font-black text-blood-500 uppercase tracking-[0.2em] mt-3"><Dumbbell size={16} /> {activeDay.focus}</p>}
                </>
             )}
          </div>

          <div className="p-6 md:p-8 space-y-6">
             {activeBlocks.map((block) => {
               const isFormVisible = visibleForms[block.id];
               const blockLogs = logs.filter(l => l.dayId === activeDay.id && l.userId === currentUserId && l.sectionTitle === block.title);

               return (
                <div key={block.id} className={`rounded-2xl border transition-all ${userRole === 'COACH' ? 'bg-dark-950 border-dark-700 p-4' : 'bg-dark-950/30 border-dark-800 p-6'}`}>
                   {userRole === 'COACH' && (
                      <div className="flex justify-between items-center mb-4 border-b border-dark-800 pb-2">
                         <input value={block.title} onChange={(e) => handleUpdateBlock(block.id, 'title', e.target.value)} className="bg-transparent text-sm font-black uppercase tracking-widest text-blood-500 focus:outline-none w-full" placeholder="NOMBRE DE SECCIÓN" />
                         <div className="flex gap-1"><button onClick={(e) => handleDuplicateBlock(e, block.id)} className="p-2 text-gray-600 hover:text-white transition-all"><Copy size={16}/></button><button onClick={(e) => handleDeleteBlock(e, block.id)} className="p-2 text-gray-600 hover:text-red-500 transition-all"><Trash2 size={16}/></button></div>
                      </div>
                   )}
                   {userRole === 'COACH' ? <AutoResizeTextarea value={block.content} onChange={(e) => handleUpdateBlock(block.id, 'content', e.target.value)} placeholder="Detalles de la sección..." className="w-full bg-transparent text-gray-200 font-mono text-sm leading-relaxed focus:outline-none" /> : (
                      <>
                        {block.title && <h3 className="text-xs font-black text-blood-500 uppercase tracking-[0.3em] mb-4 border-l-4 border-blood-600 pl-3">{block.title}</h3>}
                        <div className="font-mono text-sm md:text-base text-gray-300 leading-relaxed whitespace-pre-wrap">{block.content}</div>

                        {!activeDay.isRestDay && (
                           <div className="mt-8 border-t border-dark-800 pt-6">
                              {blockLogs.length > 0 && (
                                <div className="mb-4 space-y-3">
                                   {blockLogs.map(log => (
                                      <div key={log.id} className={`p-4 rounded-xl bg-dark-900/50 border border-dark-700 flex justify-between items-center group/log ${log.result === 'No entrené hoy' ? 'border-red-900/30 bg-red-950/10' : ''}`}>
                                         <div className="flex flex-col">
                                            <div className="flex items-center gap-2">
                                               {log.result === 'No entrené hoy' ? <XCircle size={14} className="text-red-500"/> : <Trophy size={14} className="text-yellow-600"/>}
                                               <span className={`font-mono font-black text-lg ${log.result === 'No entrené hoy' ? 'text-red-400 italic' : 'text-blood-400'}`}>
                                                  {log.result === 'No entrené hoy' ? 'FALTA' : log.result}
                                               </span>
                                            </div>
                                            {log.notes && <span className="text-[10px] text-gray-500 italic mt-1 font-medium">"{log.notes}"</span>}
                                         </div>
                                         <button onClick={() => onDeleteLog(log.id)} className="text-gray-700 hover:text-red-500 transition-colors opacity-0 group-hover/log:opacity-100">
                                            <Trash2 size={16} />
                                         </button>
                                      </div>
                                   ))}
                                </div>
                              )}

                              {!isFormVisible ? (
                                <button onClick={() => setVisibleForms(p => ({...p, [block.id]: true}))} className="w-full flex items-center justify-center gap-3 py-4 rounded-2xl border-2 border-dashed border-dark-800 text-gray-500 hover:text-white hover:border-dark-600 transition-all font-black uppercase text-xs tracking-widest"><PlusCircle size={18}/> Registrar Resultado</button>
                              ) : (
                                <div className="bg-dark-900 p-5 rounded-2xl border border-dark-700 animate-fade-in-up shadow-2xl">
                                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Resultado</label>
                                        <input type="text" placeholder="Ej: 225 lbs o 12:45..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.result || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), result: e.target.value}}))} autoFocus />
                                      </div>
                                      <div className="space-y-1">
                                        <label className="text-[10px] font-black uppercase text-blood-500 tracking-widest ml-1">Notas (Opcional)</label>
                                        <input type="text" placeholder="Sensaciones, RPE..." className="w-full bg-dark-950 border border-dark-700 rounded-xl p-4 text-white text-sm focus:border-blood-500 focus:outline-none" value={logInputs[block.id]?.notes || ''} onChange={(e) => setLogInputs(p => ({...p, [block.id]: {...(p[block.id] || {result:'', notes:''}), notes: e.target.value}}))} />
                                      </div>
                                   </div>
                                   <div className="flex gap-2"><button onClick={() => setVisibleForms(p => ({...p, [block.id]: false}))} className="flex-1 py-4 text-xs font-black uppercase text-gray-500 hover:text-white transition-all">Cancelar</button><button onClick={() => handleSaveLogForBlock(activeDay.id, block.title, block.id)} className="flex-[2] py-4 bg-blood-600 hover:bg-blood-500 text-white text-xs font-black uppercase rounded-xl transition-all shadow-lg shadow-blood-900/20">Guardar Registro</button></div>
                                </div>
                              )}
                           </div>
                        )}
                      </>
                   )}
                </div>
               );
             })}
             {userRole === 'COACH' && <button onClick={handleAddBlock} className="w-full py-6 rounded-2xl border-2 border-dashed border-dark-700 text-gray-600 hover:text-blood-500 hover:border-blood-500 transition-all font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3"><Plus size={20}/> Nueva Sección</button>}
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
           {userRole === 'ATHLETE' && !activeDay.isRestDay && (
              <div className="bg-dark-900 rounded-3xl border border-dark-800 p-6 shadow-xl">
                 <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-4">Opciones de hoy</h4>
                 {!showNoTrainForm ? <button onClick={() => setShowNoTrainForm(true)} className="w-full flex items-center justify-center gap-3 py-4 bg-dark-950 border border-red-900/20 text-red-500 rounded-2xl font-black uppercase text-xs tracking-[0.2em] hover:bg-red-950/20 transition-all active:scale-95"><XCircle size={18}/> No entrené hoy</button> : (
                    <div className="space-y-4 animate-fade-in">
                       <p className="text-xs font-bold text-red-400">¿Por qué no entrenamos hoy?</p>
                       <div className="grid grid-cols-2 gap-2">
                          {MOTIVOS_FALTA.map(m => (
