// --- UTILS ---
const parseContentToBlocks = (contentStr: string): WorkoutBlock[] => {
  try {
    const parsed = JSON.parse(contentStr);
    if (Array.isArray(parsed)) return parsed;
    throw new Error("Not an array");
  } catch (e) {
    return [{ id: Date.now().toString(), title: 'Bloque Principal', content: contentStr || '' }];
  }
};

const getMonday = (d: Date) => {
  const day = d.getDay(), diff = d.getDate() - day + (day === 0 ? -6 : 1);
  return new Date(new Date(d).setDate(diff));
};

const formatDate = (date: Date) => {
   const year = date.getFullYear();
   const month = String(date.getMonth() + 1).padStart(2, '0');
   const day = String(date.getDate()).padStart(2, '0');
   return `${year}-${month}-${day}`;
};

const getWeekDays = (startDate: Date): { id: string, date: string, dayName: string }[] => {
   const days = [];
   const dayNames = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];
   for (let i = 0; i < 7; i++) {
      const d = new Date(startDate);
      d.setDate(startDate.getDate() + i);
      days.push({ id: formatDate(d), date: formatDate(d), dayName: dayNames[i] });
   }
   return days;
};

const SESSION_KEY = 'wb_session_v1';
const TIMER_STATE_KEY = 'wb_timer_state_v1';
const THEME_KEY = 'wb_theme_mode';
const FONT_SIZE_KEY = 'wb_font_size';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isSessionChecking, setIsSessionChecking] = useState(true);
  const [viewMode, setViewMode] = useState<UserRole>('ATHLETE');
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [authError, setAuthError] = useState('');
  const [authSuccessMsg, setAuthSuccessMsg] = useState('');
  const [currentTab, setCurrentTab] = useState<AppTab>('program');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [currentWeekStart, setCurrentWeekStart] = useState<Date>(getMonday(new Date()));
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');
  const [fontSize, setFontSize] = useState<'sm' | 'base' | 'lg' | 'xl'>('base');
  const [programData, setProgramData] = useState<ProgramWeek>({ weekNumber: 1, startDate: formatDate(getMonday(new Date())), days: [] });
  const [workoutLogs, setWorkoutLogs] = useState<WorkoutLog[]>([]);
  const [athleteRecords, setAthleteRecords] = useState<AthleteRecord[]>([]);
  const [rmWeight, setRmWeight] = useState<string>('');
  const [timerState, setTimerState] = useState<TimerGlobalState>({
     isActive: false, startTime: 0, pausedAt: null, totalPausedTime: 0, mode: 'AMRAP',
     config: { mode: 'AMRAP', timeCapMinutes: 10, intervalMinutes: 1, workSeconds: 20, restSeconds: 10, rounds: 8 }
  });

  const unreadCount = notifications.filter(n => !n.isRead).length;

  // Initial Theme & Font Setup
  useEffect(() => {
    const savedTheme = localStorage.getItem(THEME_KEY) as 'dark' | 'light' | null;
    const savedFontSize = localStorage.getItem(FONT_SIZE_KEY) as any;

    const initialTheme = savedTheme || 'dark';
    setTheme(initialTheme);
    if (initialTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    if (savedFontSize) setFontSize(savedFontSize);
  }, []);

  const toggleTheme = () => {
    const newTheme = theme === 'dark' ? 'light' : 'dark';
    setTheme(newTheme);
    localStorage.setItem(THEME_KEY, newTheme);
    if (newTheme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  const cycleFontSize = () => {
    const sizes: ('sm' | 'base' | 'lg' | 'xl')[] = ['sm', 'base', 'lg', 'xl'];
    const currentIndex = sizes.indexOf(fontSize);
    const nextIndex = (currentIndex + 1) % sizes.length;
    const nextSize = sizes[nextIndex];
    setFontSize(nextSize);
    localStorage.setItem(FONT_SIZE_KEY, nextSize);
  };

  const getFontSizeClass = () => {
    switch (fontSize) {
      case 'sm': return 'text-[0.9rem]';
      case 'lg': return 'text-[1.1rem]';
      case 'xl': return 'text-[1.2rem]';
      default: return 'text-[1rem]';
    }
  };

  useEffect(() => {
     const storedTimer = localStorage.getItem(TIMER_STATE_KEY);
     if (storedTimer) {
        try {
           const parsed = JSON.parse(storedTimer);
           if (parsed && typeof parsed.startTime === 'number') setTimerState(parsed);
        } catch (e) { console.error(e); }
     }
  }, []);

  useEffect(() => { localStorage.setItem(TIMER_STATE_KEY, JSON.stringify(timerState)); }, [timerState]);

  const refreshData = async () => {
    if (!currentUser) return;
    try {
      const { data: usersData } = await supabase.from('app_users').select('*');
      if (usersData) setAllUsers(usersData.map((u: any) => ({ id: u.id, username: u.username, role: u.role, fullName: u.full_name, isApproved: u.is_approved })));

      const weekDays = getWeekDays(currentWeekStart);
      const startStr = weekDays[0].date;
      const endStr = weekDays[6].date;
      const { data: workoutsData } = await supabase.from('daily_workouts').select('*').gte('date', startStr).lte('date', endStr);

      const mergedDays: WorkoutDay[] = weekDays.map(wd => {
         const found = workoutsData?.find((w: any) => w.date === wd.date);
         return found ? {
            id: wd.date, date: wd.date, dayName: wd.dayName, title: found.title || 'Sin Título',
            focus: found.focus || '', content: found.content || '', blocks: parseContentToBlocks(found.content || ''), isRestDay: found.is_rest_day
         } : { id: wd.date, date: wd.date, dayName: wd.dayName, title: 'Descanso / Programar', focus: '', content: '', blocks: [], isRestDay: false };
      });
      setProgramData({ weekNumber: 1, startDate: startStr, days: mergedDays });

      const { data: logsData } = await supabase.from('workout_logs').select('*').order('date', { ascending: true });
      if (logsData) setWorkoutLogs(logsData.map((l: any) => ({ id: l.id, userId: l.user_id, dayId: l.day_id, section_title: l.section_title, result: l.result, notes: l.notes, date: l.date })));

      const { data: recordsData } = await supabase.from('athlete_records').select('*');
      if (recordsData) setAthleteRecords(recordsData.map((r: any) => ({ id: r.id, userId: r.user_id, category: r.category, exercise: r.exercise, value: r.value, unit: r.unit })));

      const { data: notifData } = await supabase.from('app_notifications').select('*').or(`receiver_id.eq.${currentUser.id},receiver_id.is.null`).order('created_at', { ascending: false });
      if (notifData) setNotifications(notifData.map((n: any) => ({ id: n.id, senderId: n.sender_id, receiverId: n.receiver_id, message: n.message, isRead: n.is_read, createdAt: n.created_at })));
    } catch (e) { console.error(e); }
  };

  useEffect(() => {
    const restoreSession = async () => {
      setIsSessionChecking(true);
      const storedSession = localStorage.getItem(SESSION_KEY);
      if (storedSession) {
        try {
          const { userId, expiry } = JSON.parse(storedSession);
          if (Date.now() > expiry) { localStorage.removeItem(SESSION_KEY); setIsSessionChecking(false); return; }
          const { data, error } = await supabase.from('app_users').select('*').eq('id', userId).single();
          if (data && !error && data.is_approved) {
             setCurrentUser({ id: data.id, username: data.username, role: data.role, fullName: data.full_name, isApproved: data.is_approved });
             setViewMode(data.role);
          } else localStorage.removeItem(SESSION_KEY);
        } catch (e) { localStorage.removeItem(SESSION_KEY); }
      }
      setIsSessionChecking(false);
    };
    restoreSession();
  }, []);

  useEffect(() => { if (currentUser) refreshData(); }, [currentUser, currentWeekStart]);

  const handleUpdateProgramDay = async (updatedDay: WorkoutDay) => {
     setProgramData(prev => ({ ...prev, days: prev.days.map(d => d.id === updatedDay.id ? updatedDay : d) }));
     await supabase.from('daily_workouts').upsert({ date: updatedDay.date, title: updatedDay.title, focus: updatedDay.focus, content: JSON.stringify(updatedDay.blocks), is_rest_day: updatedDay.isRestDay });
  };

  const handleWeekChange = (direction: 'prev' | 'next') => {
    const newDate = new Date(currentWeekStart);
    newDate.setDate(newDate.getDate() + (direction === 'next' ? 7 : -7));
    setCurrentWeekStart(newDate);
  };

  const handleAddLog = async (newLog: WorkoutLog) => {
    setWorkoutLogs(prev => [...prev, newLog]);
    const { error } = await supabase.from('workout_logs').insert({ id: newLog.id, user_id: newLog.userId, day_id: newLog.dayId, section_title: newLog.sectionTitle || '', result: newLog.result, notes: newLog.notes, date: newLog.date });
    if (error) { setWorkoutLogs(prev => prev.filter(l => l.id !== newLog.id)); alert(`Error: ${error.message}`); }
  };

  const handleUpdateLog = async (updatedLog: WorkoutLog) => {
    setWorkoutLogs(prev => prev.map(l => l.id === updatedLog.id ? updatedLog : l));
    await supabase.from('workout_logs').update({ result: updatedLog.result, notes: updatedLog.notes }).eq('id', updatedLog.id);
  };

  const handleDeleteLog = async (logId: string) => {
    setWorkoutLogs(prev => prev.filter(l => l.id !== logId));
    await supabase.from('workout_logs').delete().eq('id', logId);
  };

  const handleSaveAthleteRecord = async (category: any, exercise: string, value: string, unit: string) => {
     if (!currentUser) return;
     const newRecord: AthleteRecord = { id: Date.now().toString(), userId: currentUser.id, category, exercise, value, unit };
     setAthleteRecords(prev => [ ...prev.filter(r => !(r.userId === currentUser.id && r.exercise === exercise)), newRecord ]);
     await supabase.from('athlete_records').upsert({ user_id: currentUser.id, category, exercise, value, unit }, { onConflict: 'user_id, exercise' });
  };

  const handleLogin = async (username: string, pass: string) => {
    setAuthError('');
    const { data, error } = await supabase.from('app_users').select('*').ilike('username', username).eq('password', pass).single();
    if (error || !data) setAuthError('Usuario o contraseña incorrectos.');
    else {
      if (!data.is_approved) { setAuthError('Acceso denegado. No ha pagado la programación.'); return; }
      setCurrentUser({ id: data.id, username: data.username, role: data.role, fullName: data.full_name, isApproved: data.is_approved });
      localStorage.setItem(SESSION_KEY, JSON.stringify({ userId: data.id, expiry: Date.now() + (7 * 24 * 60 * 60 * 1000) }));
      setViewMode(data.role);
      setCurrentTab('program');
    }
  };

  const handleRegister = async (username: string, pass: string, fullName: string) => {
    setAuthError('');
    const { data: existing } = await supabase.from('app_users').select('id').ilike('username', username).single();
    if (existing) { setAuthError('El usuario ya existe.'); return; }
    const { error } = await supabase.from('app_users').insert({ username, password: pass, full_name: fullName, role: 'ATHLETE', is_approved: false });
    if (error) setAuthError('Error al crear cuenta.');
    else setAuthSuccessMsg('¡Cuenta creada! Espera aprobación.');
  };

  const handleLogout = () => { localStorage.removeItem(SESSION_KEY); setCurrentUser(null); setCurrentTab('program'); };

  const renderContent = () => {
    switch (currentTab) {
      case 'program': return <WildBloodView programData={programData} setProgramData={() => {}} onUpdateDay={handleUpdateProgramDay} onWeekChange={handleWeekChange} userRole={viewMode} logs={workoutLogs} onAddLog={handleAddLog} onDeleteLog={handleDeleteLog} onUpdateLog={handleUpdateLog} currentUserId={currentUser!.id} />;
      case 'timer': return <SmartTimer programDays={programData.days} onSaveLog={handleAddLog} currentUserId={currentUser!.id} globalState={timerState} onStateChange={setTimerState} />;
      case 'calc': return <RMCalculator athleteRecords={athleteRecords.filter(r => r.userId === currentUser!.id)} savedWeight={rmWeight} onWeightChange={setRmWeight} />;
      case 'logs': return <LogBook logs={workoutLogs} users={allUsers} days={programData.days} currentUser={{...currentUser!, role: viewMode}} onDeleteLog={handleDeleteLog}/>; 
      case 'profile': return <div className="px-4 py-6 max-w-4xl mx-auto"><div className="mb-8 flex items-center justify-between"><div className="flex items-center gap-4"><div className="w-16 h-16 rounded-full bg-blood-600 text-white flex items-center justify-center font-black text-2xl"><UserIcon size={32} /></div><div><h2 className="text-2xl font-black text-gray-900 dark:text-white italic uppercase">{currentUser!.fullName}</h2><p className="text-xs text-blood-500 font-bold tracking-widest uppercase">{currentUser!.role} @{currentUser!.username}</p></div></div><button onClick={handleLogout} className="flex items-center gap-2 bg-slate-100 dark:bg-dark-800 hover:bg-red-900/20 text-red-500 px-4 py-2 rounded-xl transition-all border border-slate-200 dark:border-dark-700 font-bold uppercase text-[10px] tracking-widest"><LogOut size={14} /> Salir</button></div><AthleteProfile userId={currentUser!.id} records={athleteRecords.filter(r => r.userId === currentUser!.id)} onSaveRecord={handleSaveAthleteRecord} /></div>;
      case 'users': return currentUser!.role === 'COACH' && viewMode === 'COACH' ? <UserManagement users={allUsers} currentUser={currentUser!} onUpdateRole={async (id, role) => { setAllUsers(prev => prev.map(u => u.id === id ? {...u, role} : u)); await supabase.from('app_users').update({role}).eq('id', id); }} onToggleStatus={async (id, status) => { setAllUsers(prev => prev.map(u => u.id === id ? {...u, isApproved: status} : u)); await supabase.from('app_users').update({is_approved: status}).eq('id', id); }} onDeleteUser={async (id) => { setAllUsers(prev => prev.filter(u => u.id !== id)); await supabase.from('workout_logs').delete().eq('user_id', id); await supabase.from('app_users').delete().eq('id', id); }} /> : null;
      default: return null;
    }
  };

  if (isSessionChecking) return <div className="min-h-screen bg-slate-50 dark:bg-dark-950 flex items-center justify-center"><div className="w-12 h-12 border-4 border-blood-900 border-t-blood-500 rounded-full animate-spin"></div></div>;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} onRegister={handleRegister} error={authError} successMessage={authSuccessMsg} />;

  const navigationItems = [
    { id: 'program', icon: Dumbbell, label: 'WOD' },
    { id: 'logs', icon: ClipboardList, label: 'Diario' },
    { id: 'calc', icon: Calculator, label: 'RM' },
    { id: 'timer', icon: Timer, label: 'Timer' },
    { id: 'profile', icon: UserIcon, label: 'Perfil' },
    ...(currentUser.role === 'COACH' && viewMode === 'COACH' ? [{ id: 'users', icon: Users, label: 'Equipo' } as const] : []),
  ];

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-dark-950 text-gray-800 dark:text-gray-200 flex flex-col md:flex-row font-sans selection:bg-blood-500/30 ${getFontSizeClass()}`}>

      {/* SIDEBAR (Desktop) */}
      <aside className="hidden md:flex md:w-64 bg-white dark:bg-dark-900 border-r border-slate-200 dark:border-dark-800 flex-col h-screen sticky top-0 transition-colors">
        <div className="p-6">
           <div className="w-full flex items-center justify-center mb-8">
              <img src="https://crmkfsetelysptocfbtd.supabase.co/storage/v1/object/public/imagenes/WildBlood.png" className="w-24 h-24 object-contain drop-shadow-2xl" alt="Logo" />
           </div>
           <nav className="space-y-2">
              {navigationItems.map(item => (
                 <button 
                   key={item.id} 
                   onClick={() => setCurrentTab(item.id as AppTab)}
                   className={`w-full flex items-center gap-4 px-4 py-3 rounded-xl font-bold uppercase text-xs tracking-widest transition-all ${currentTab === item.id ? 'bg-blood-600 text-white shadow-lg shadow-blood-900/40' : 'text-slate-500 dark:text-gray-500 hover:bg-slate-50 dark:hover:bg-dark-800 hover:text-gray-900 dark:hover:text-gray-200'}`}
                 >
                    <item.icon size={20} />
                    {item.label}
                 </button>
              ))}
           </nav>
        </div>
        <div className="mt-auto p-6 border-t border-slate-200 dark:border-dark-800">
           {currentUser.role === 'COACH' && (
              <button onClick={() => setViewMode(prev => prev === 'COACH' ? 'ATHLETE' : 'COACH')} className="w-full mb-4 px-4 py-2 bg-slate-100 dark:bg-dark-800 hover:bg-slate-200 dark:hover:bg-dark-700 text-blood-500 text-[10px] font-black uppercase rounded-lg border border-slate-200 dark:border-dark-700 flex items-center justify-center gap-2">
                 {viewMode === 'COACH' ? <Edit3 size={14}/> : <Eye size={14}/>}
                 {viewMode === 'COACH' ? 'Modo Coach' : 'Vista Atleta'}
              </button>
           )}
           <button onClick={handleLogout} className="w-full flex items-center gap-4 px-4 py-3 text-slate-400 dark:text-gray-500 hover:text-red-500 transition-colors uppercase font-bold text-xs">
              <LogOut size={20}/>
              Salir
           </button>
        </div>
      </aside>

      {/* MAIN CONTENT AREA */}
      <div className="flex-1 flex flex-col min-h-screen transition-colors">
        <header className="flex justify-between items-center p-4 bg-white dark:bg-dark-950 border-b border-slate-200 dark:border-dark-800 md:bg-transparent md:border-none">
          <div className="md:hidden">
             <img src="https://crmkfsetelysptocfbtd.supabase.co/storage/v1/object/public/imagenes/WildBlood.png" className="w-8 h-8 object-contain" alt="Logo" />
          </div>
          <div className="flex items-center gap-2 ml-auto">

             {/* FONT SIZE TOGGLE */}
             <button 
               onClick={cycleFontSize} 
               className="p-2 text-slate-500 dark:text-gray-400 hover:text-blood-500 transition-colors bg-slate-100 dark:bg-dark-800 rounded-full flex items-center gap-1"
               title="Tamaño de texto"
             >
                <Type size={20} />
                <span className="text-[10px] font-black uppercase pr-1">{fontSize.toUpperCase()}</span>
             </button>

             {/* THEME TOGGLE BUTTON */}
             <button 
               onClick={toggleTheme} 
               className="p-2 text-slate-500 dark:text-gray-400 hover:text-blood-500 transition-colors bg-slate-100 dark:bg-dark-800 rounded-full"
               title={theme === 'dark' ? "Modo Claro" : "Modo Oscuro"}
             >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
             </button>

             <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="p-2 text-slate-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white relative">
                   <Bell size={20} />
                   {unreadCount > 0 && <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-blood-600 rounded-full border-2 border-white dark:border-dark-950"></span>}
                </button>
                {showNotifDropdown && (
                   <div className="absolute right-0 top-full mt-2 w-80 bg-white dark:bg-dark-800 border border-slate-200 dark:border-dark-700 rounded-2xl shadow-2xl z-50 overflow-hidden">
                      <div className="p-4 bg-slate-50 dark:bg-dark-900 border-b border-slate-200 dark:border-dark-700 flex justify-between items-center"><span className="text-[10px] font-black uppercase text-gray-500">Notificaciones</span><button onClick={() => refreshData()} className="text-gray-500 hover:text-gray-900 dark:hover:text-white"><RefreshCw size={14}/></button></div>
                      <div className="max-h-80 overflow-y-auto">
                         {notifications.length === 0 ? <div className="p-8 text-center text-gray-400 text-xs italic">Nada nuevo por aquí...</div> : notifications.map(notif => (
                            <div key={notif.id} onClick={() => !notif.isRead && supabase.from('app_notifications').update({is_read: true}).eq('id', notif.id).then(() => setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, isRead: true} : n)))} className={`p-4 border-b border-slate-100 dark:border-dark-700/50 cursor-pointer transition-colors ${!notif.isRead ? 'bg-blood-900/5' : 'opacity-60'}`}>
                               <p className={`text-sm ${!notif.isRead ? 'text-gray-900 dark:text-white font-bold' : 'text-gray-500'}`}>{notif.message}</p>
                               <span className="text-[10px] text-gray-400 dark:text-gray-600 mt-2 block">{new Date(notif.createdAt).toLocaleDateString()}</span>
                            </div>
                         ))}
                      </div>
                   </div>
                )}
             </div>
          </div>
        </header>

        <main className="flex-1 overflow-y-auto custom-scrollbar transition-all">
           <div className="max-w-6xl mx-auto md:p-6 pb-24 md:pb-6">
              {renderContent()}
           </div>
        </main>
      </div>

      {/* BOTTOM NAV (Mobile Only) */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-white/90 dark:bg-dark-900/90 backdrop-blur-xl border-t border-slate-200 dark:border-dark-800 z-50 pb-safe shadow-[0_-10px_30px_rgba(0,0,0,0.1)] dark:shadow-[0_-10px_30px_rgba(0,0,0,0.5)] transition-colors">
         <div className="flex justify-around items-center h-16">
            {navigationItems.map(item => (
               <button 
                 key={item.id} 
                 onClick={() => setCurrentTab(item.id as AppTab)}
                 className={`flex flex-col items-center justify-center flex-1 h-full transition-all ${currentTab === item.id ? 'text-blood-500 scale-110' : 'text-slate-400 dark:text-gray-600'}`}
               >
                  <item.icon size={22} strokeWidth={currentTab === item.id ? 2.5 : 2} />
                  <span className="text-[8px] font-black uppercase tracking-widest mt-1">{item.label}</span>
               </button>
            ))}
         </div>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ProgramWeek, WorkoutDay, UserRole, WorkoutLog, WorkoutBlock } from '../types';
import { 
  Dumbbell, Save, Calendar, CheckCircle, Coffee, Plus, Trash2, Copy, 
  ExternalLink, ChevronLeft, ChevronRight, Edit2, X, PlusCircle, 
  XCircle, AlertCircle, Clock, HeartPulse, Plane, ZapOff, Trophy 
} from 'lucide-react';

interface WildBloodViewProps {
  programData: ProgramWeek;
  setProgramData: (data: ProgramWeek) => void;
  onUpdateDay: (day: WorkoutDay) => void;
  onWeekChange: (direction: 'prev' | 'next') => void;
  userRole: UserRole;
  logs: WorkoutLog[];
  onAddLog: (log: WorkoutLog) => void;
  onDeleteLog: (logId: string) => void;
  onUpdateLog: (log: WorkoutLog) => void;
  currentUserId: string;
}

const MOTIVOS_FALTA = [
  { id: 'Lesión', icon: HeartPulse, label: 'Lesión/Dolor' },
  { id: 'Tiempo', icon: Clock, label: 'Trabajo/Tiempo' },
  { id: 'Salud', icon: AlertCircle, label: 'Enfermedad' },
  { id: 'Viaje', icon: Plane, label: 'Viaje' },
  { id: 'Descanso', icon: ZapOff, label: 'Fatiga/Descanso' },
];

const AutoResizeTextarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = (props) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const adjustHeight = () => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${textarea.scrollHeight}px`;
    }
  };
  useEffect(() => { adjustHeight(); }, [props.value]);
  return (
    <textarea
      ref={textareaRef}
      {...props}
      onChange={(e) => { adjustHeight(); if (props.onChange) props.onChange(e); }}
      className={`${props.className} overflow-hidden resize-none box-border`}
      rows={1}
    />
  );
};

export const WildBloodView: React.FC<WildBloodViewProps> = ({ programData, onUpdateDay, onWeekChange, userRole, logs, onAddLog, onDeleteLog, onUpdateLog, currentUserId }) => {
  const getTodayId = () => {
     const d = new Date();
     return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  };

  const [selectedDayId, setSelectedDayId] = useState<string>(getTodayId());
  const [logInputs, setLogInputs] = useState<Record<string, {result: string, notes: string}>>({});
  const [visibleForms, setVisibleForms] = useState<Record<string, boolean>>({});
  const [editingLogId, setEditingLogId] = useState<string | null>(null);
  const [showNoTrainForm, setShowNoTrainForm] = useState(false);
  const [noTrainReason, setNoTrainReason] = useState('');
  const [noTrainNotes, setNoTrainNotes] = useState('');

  useEffect(() => {
     const exists = programData.days.find(d => d.id === selectedDayId);
     if (!exists && programData.days.length > 0) setSelectedDayId(programData.days[0].id);
  }, [programData]);

  const activeDay = programData.days.find(d => d.id === selectedDayId) || programData.days[0] || { id: 'temp', date: '', dayName: '', title: '', focus: '', content: '', blocks: [], isRestDay: false };
  const activeBlocks = activeDay.blocks || [];

  const handleDayChange = (field: keyof WorkoutDay, value: any) => {
    if (userRole !== 'COACH') return;
    onUpdateDay({ ...activeDay, [field]: value });
  };

  const handleUpdateBlock = (blockId: string, field: keyof WorkoutBlock, value: string) => {
    if (userRole !== 'COACH') return;
    const newBlocks = activeBlocks.map(b => b.id === blockId ? { ...b, [field]: value } : b);
    handleDayChange('blocks', newBlocks);
  };

  const generateId = () => Date.now().toString() + Math.random().toString(36).substr(2, 5);

  const handleAddBlock = () => handleDayChange('blocks', [...activeBlocks, { id: generateId(), title: 'Nueva Sección', content: '' }]);
  const handleDuplicateBlock = (e: React.MouseEvent, blockId: string) => {
    e.stopPropagation();
    const blockToCopy = activeBlocks.find(b => b.id === blockId);
    if (!blockToCopy) return;
    const newBlocks = [...activeBlocks];
    newBlocks.splice(activeBlocks.findIndex(b => b.id === blockId) + 1, 0, { ...blockToCopy, id: generateId(), title: `${blockToCopy.title} (Copia)` });
    handleDayChange('blocks', newBlocks);
  };
  const handleDeleteBlock = (e: React.MouseEvent, blockId: string) => { e.stopPropagation(); handleDayChange('blocks', activeBlocks.filter(b => b.id !== blockId)); };

  const handleSaveLogForBlock = (dayId: string, blockTitle: string, blockId: string) => {
    const input = logInputs[blockId] || {result: '', notes: ''};
    if (!input.result.trim()) return;
    if (editingLogId) onUpdateLog({ id: editingLogId, userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    else onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId, sectionTitle: blockTitle, result: input.result, notes: input.notes, date: new Date().toISOString() });
    setLogInputs(prev => ({ ...prev, [blockId]: {result: '', notes: ''} }));
    setVisibleForms(prev => ({ ...prev, [blockId]: false }));
    setEditingLogId(null);
  };

  const handleConfirmNoTraining = () => {
    if (!noTrainReason) return;
    onAddLog({ id: Date.now().toString(), userId: currentUserId, dayId: activeDay.id, sectionTitle: 'Asistencia', result: 'No entrené hoy', notes: `Motivo: ${noTrainReason}. ${noTrainNotes}`, date: new Date().toISOString() });
    setShowNoTrainForm(false); setNoTrainReason(''); setNoTrainNotes('');
  };

  const formatTabDate = (dateStr: string) => new Date(dateStr + 'T00:00:00').getDate();
  const weeklyTrainingDays = programData.days.filter(d => !d.isRestDay).length;
  const completedDaysCount = programData.days.filter(day => logs.some(l => l.dayId === day.id && l.userId === currentUserId && l.result !== 'No entrené hoy')).length;
  const adherencePct = weeklyTrainingDays > 0 ? Math.round((completedDaysCount / weeklyTrainingDays) * 100) : 0;

  return (
    <div className="flex flex-col h-full animate-fade-in">
      <div className="mb-6 px-4 md:px-0">

        {/* HEADER CENTRADO */}
        <div className="flex flex-col items-center mb-6">
           <div className="flex items-center justify-between w-full max-w-md gap-4 bg-white dark:bg-dark-900/30 p-4 rounded-2xl border border-slate-200 dark:border-dark-800 shadow-xl transition-colors">
              <button 
                onClick={() => onWeekChange('prev')} 
                className="bg-slate-100 dark:bg-dark-800 p-3 rounded-xl text-slate-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-all active:scale-90"
              >
                <ChevronLeft size={24}/>
              </button>

              <div className="text-center flex-1">
                 <h1 className="text-3xl md:text-4xl font-black text-blood-600 italic uppercase tracking-tighter leading-none">Wild Blood</h1>
                 <p className="text-[10px] text-slate-500 dark:text-gray-500 uppercase tracking-[0.2em] font-black mt-1 opacity-70">Semana del {programData.startDate}</p>
              </div>

              <button 
                onClick={() => onWeekChange('next')} 
                className="bg-slate-100 dark:bg-dark-800 p-3 rounded-xl text-slate-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white transition-all active:scale-90"
              >
                <ChevronRight size={24}/>
              </button>
           </div>

           {/* BARRA DE PORCENTAJE */}
           <div className="w-full max-w-md mt-6 px-2">
              <div className="flex justify-between items-end mb-1.5 px-1">
                 <span className="text-[10px] font-black text-slate-600 dark:text-gray-400 uppercase tracking-widest">Adherencia Semanal</span>
